import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface AIAnalysisResult {
  isAppropriate: boolean;
  refinedTitle?: string;
  refinedContent?: string;
  advice?: string;
}

export const analyzeProposal = async (title: string, content: string): Promise<AIAnalysisResult> => {
  try {
    const model = 'gemini-2.5-flash-latest'; // Using Flash for speed as per guidelines

    const prompt = `
      あなたは学校の生徒会目安箱のAIアシスタントです。
      生徒が投稿しようとしている意見（タイトルと内容）を分析し、以下のJSON形式で回答してください。

      1. isAppropriate: 誹謗中傷や暴言、不適切な内容が含まれていないか判定（true/false）。
      2. refinedTitle: タイトルをより明確で建設的なものに改善案があれば提示（なければ元のまま）。
      3. refinedContent: 内容をより説得力があり、丁寧な文章にするための改善案（なければ元のまま）。
      4. advice: 生徒へのアドバイス（「具体的に〇〇を書くと伝わりやすいです」など）。

      タイトル: ${title}
      内容: ${content}

      回答はJSONのみを返してください。
    `;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json"
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const result = JSON.parse(text) as AIAnalysisResult;
    return result;

  } catch (error) {
    console.error("Gemini analysis failed:", error);
    // Fallback in case of error: assume appropriate but warn
    return {
      isAppropriate: true,
      advice: "AIチェックに失敗しましたが、このまま投稿可能です。内容を再度確認してください。"
    };
  }
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
