}

interface Signature {
  userId: string;
  userName: string;
  timestamp: string;
}

interface Proposal {
  id: number;
  title: string;
  content: string;
  category: string;
  status: '受付中' | '検討中' | '先生と調整中' | '対応済';
  adminResponse: string;
  timestamp: string;
  signatures: Signature[];
}

interface NewsItem {
  id: number;
  title: string;
  content: string;
  timestamp: string;
  author: string;
}

// --- Constants ---
