      setAiAnalysis(null);
  };

  const handlePostSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!isAIApproved) return;

    const newId = proposals.length > 0 ? Math.max(...proposals.map(p => p.id)) + 1 : 1;
    const newProposal: Proposal = {
      id: newId,
      title: postForm.title,
      content: postForm.content,
      category: postForm.category,
      status: '受付中',
      adminResponse: '',
      timestamp: new Date().toISOString(),
      signatures: []
    };
    const updated = [newProposal, ...proposals];
    setProposals(updated);
    localStorage.setItem('schoolProposals', JSON.stringify(updated));
    setPostForm({ title: '', content: '', category: '' });
    setAiAnalysis(null);
    setIsAIApproved(false);
    setIsPostModalOpen(false);
  };

  const handleAIAnalyze = async () => {
    if (!postForm.title || !postForm.content || !postForm.category) {
        alert("タイトル、カテゴリー、内容をすべて入力してからAIチェックを実行してください。");
        return;
    }
    setAiAnalysis({ advice: '', loading: true });
    setIsAIApproved(false);

    const result = await analyzeProposal(postForm.title, postForm.content, postForm.category);

    setAiAnalysis({ 
        advice: result.advice || 'チェックが完了しました。', 
        loading: false 
    });
    setIsAIApproved(result.isAppropriate);

    if (result.isAppropriate) {
        if (result.refinedTitle) setPostForm(prev => ({ ...prev, title: result.refinedTitle! }));
        if (result.refinedContent) setPostForm(prev => ({ ...prev, content: result.refinedContent! }));
    }
  };

