import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface AIAnalysisResult {
  isAppropriate: boolean;
  refinedTitle?: string;
  refinedContent?: string;
  advice?: string;
}

export const analyzeProposal = async (title: string, content: string, category: string): Promise<AIAnalysisResult> => {
  try {
    // Updated to a currently valid model name to resolve 404 errors.
    const model = 'gemini-2.0-flash-exp'; 

    const prompt = `
      あなたは学校の生徒会目安箱のAIアシスタントです。
      生徒が投稿しようとしている意見（タイトル、内容、選択されたカテゴリー）を総合的に分析し、以下のJSON形式で回答してください。

      カテゴリー: ${category}
      タイトル: ${title}
      内容: ${content}

      分析基準:
      1. 誹謗中傷、暴言、個人攻撃、公序良俗に反する内容が含まれていないか。
      2. 選択された「カテゴリー」と投稿内容が著しく矛盾していないか（例：「校則」の話なのに「その他」になっているなど）。
      3. 内容に含まれるハッシュタグが不適切でないか。

      出力フォーマット (JSON):
      1. isAppropriate: 上記基準に照らして投稿して問題ないか（true/false）。少しでも攻撃的であれば false にしてください。
      2. refinedTitle: タイトルをより明確で建設的なものに改善案があれば提示（なければ元のまま）。
      3. refinedContent: 内容をより説得力があり、丁寧な文章にするための改善案。ハッシュタグの提案も含めて良い。（なければ元のまま）。
      4. advice: 生徒へのアドバイス。不適切な場合はその理由を優しく伝えてください。適切な場合も、より良くするためのヒントを提示してください。

      回答はJSONのみを返してください。
    `;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json"
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const result = JSON.parse(text) as AIAnalysisResult;
    return result;

  } catch (error) {
    console.error("Gemini analysis failed:", error);
    // Fallback: Default to false to be safe if AI fails, forcing user to try again or check manually if we had manual review.
    // For this app, we'll allow it with a warning but set isAppropriate to true to avoid blocking in case of API outage, 
    // but in a strict real-world scenario, this might be false.
    return {
      isAppropriate: true,
      advice: "AIチェックに接続できませんでしたが、一時的に承認とします。内容を自己責任で確認してください。"
    };
  }
};

