import { GoogleGenAI, Type, Schema } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface AIAnalysisResult {
  isAppropriate: boolean;
  refinedTitle?: string;
  refinedContent?: string;
  advice?: string;
}

export const analyzeProposal = async (title: string, content: string, category: string): Promise<AIAnalysisResult> => {
  try {
    const model = 'gemini-2.0-flash-exp'; 

    const prompt = `
      あなたは中学校の生徒会目安箱の「AIアドバイザー」です。
      生徒が投稿しようとしている意見（タイトル、内容、カテゴリー）を読み、教育的な観点からアドバイスを行ってください。

      入力情報:
      - カテゴリー: ${category}
      - タイトル: ${title}
      - 内容: ${content}

      分析基準（以下のいずれかに該当する場合は「不適切(false)」と判定）:
      1. 個人を特定して攻撃したり、傷つけたりする内容（先生や他の生徒の実名・あだ名を含む批判など）。
      2. 暴言、汚い言葉遣い、脅迫的な表現。
      3. 公序良俗に反する内容。
      4. カテゴリーと内容が全く関係ない場合（単なるミスなら指摘してあげる）。

      役割:
      - 不適切な場合: 「なぜそれがダメなのか」を優しく、しかしはっきりと伝えてください。感情的にならず、どう書き直せば意見として受け入れられるかを提案してください。
      - 適切な場合: より説得力を増すためのヒント（理由を詳しく書く、数字を入れるなど）や、応援のメッセージを伝えてください。

      必ずJSON形式で以下の項目を含めてください。
    `;

    const schema: Schema = {
      type: Type.OBJECT,
      properties: {
        isAppropriate: {
          type: Type.BOOLEAN,
          description: "投稿内容がガイドラインに沿っていて適切かどうか。少しでも攻撃的・不適切な要素があればfalse。",
        },
        refinedTitle: {
          type: Type.STRING,
          description: "タイトルをより明確で建設的なものにするための改善案。変更不要なら元のタイトルのまま。",
        },
        refinedContent: {
          type: Type.STRING,
          description: "内容をより説得力があり、丁寧な文章にするための改善案。不適切な表現を取り除いた例など。変更不要なら元の内容のまま。",
        },
        advice: {
          type: Type.STRING,
          description: "生徒への具体的なフィードバック。なぜ修正が必要なのか、あるいはどこが良かったのかを、中学生に伝わる優しい口調で記述すること。必須。",
        },
      },
      required: ["isAppropriate", "refinedTitle", "refinedContent", "advice"],
    };

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const result = JSON.parse(text) as AIAnalysisResult;
    return result;

  } catch (error) {
    console.error("Gemini analysis failed:", error);
    // Fallback in case of error
    return {
      isAppropriate: false, // Error時は安全のためfalseにする
      advice: "申し訳ありません。AIチェック機能に一時的な不具合が発生しています。時間をおいて再度お試しください。エラーが続く場合は、内容を見直して再度投稿してみてください。"
    };
  }
};

