      const lower = searchTerm.toLowerCase();
      res = res.filter(p => p.title.toLowerCase().includes(lower) || p.content.toLowerCase().includes(lower));
    }
    if (sortOrder === 'newest') {
      res.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
