        {
          id: 1,
          title: '靴下の色にグレーを追加して欲しい',
          content: '靴下の色は黒・白・紺のみですが、友達の学校ではグレーも良いそうです。なぜグレーがダメなのかわかりません。グレーの追加をお願いします。 #靴下',
          category: '校則',
          status: '先生と調整中',
          adminResponse: '生徒総会での議論を経て、職員会議に提案中です。',
          timestamp: new Date().toISOString(),
          signatures: []
        },
        {
          id: 2,
          title: '食堂のメニューに麺類を追加してほしい',
          content: '今はパンとおにぎりしかありません。温かい麺類（うどんやラーメン）が食べたいです。 #食堂 #ランチ #改善希望',
          category: '設備・環境',
          status: '受付中',
          adminResponse: '',
          timestamp: new Date(Date.now() - 86400000).toISOString(),
          signatures: [{ userId: 'demo', userName: 'デモ太郎', timestamp: new Date().toISOString() }]
        },
        {
          id: 3,
          title: '図書室の開館時間を延長してください',
          content: '放課後、部活の前にもう少し勉強したいのですが、すぐに閉まってしまいます。あと30分延長できませんか？',
          category: '設備・環境',
          status: '対応済',
          adminResponse: '試験期間中のみ、18:00まで延長することが決定しました。',
          timestamp: new Date(Date.now() - 172800000).toISOString(),
          signatures: []
        }
      ];
      setProposals(seeds);
      localStorage.setItem('schoolProposals', JSON.stringify(seeds));
    }

    const savedNews = localStorage.getItem('schoolNews');
    if (savedNews) setNews(JSON.parse(savedNews));
    else {
        const seedNews: NewsItem[] = [
            { id: 1, title: 'アプリ「ProPoSal」運用開始！', content: '新しいデジタル目安箱がスタートしました。', timestamp: '2025-11-22T10:00:00.000Z', author: '生徒会' }
        ];
        setNews(seedNews);
        localStorage.setItem('schoolNews', JSON.stringify(seedNews));
    }

    const savedTheme = localStorage.getItem('theme') as 'light' | 'dark';
    if (savedTheme) setTheme(savedTheme || 'light');
  }, []);

  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('theme', theme);
  }, [theme]);

  // Google Login Logic
  const loginWithGoogle = useGoogleLogin({
    onSuccess: async (tokenResponse) => {
      try {
        const res = await fetch('https://www.googleapis.com/oauth2/v3/userinfo', {
          headers: { Authorization: `Bearer ${tokenResponse.access_token}` },
        });
        const userInfo = await res.json();
        setUser({
          id: userInfo.email,
          email: userInfo.email,
          name: userInfo.name,
          role: userInfo.email.includes('admin') ? 'admin' : 'student',
          class: '未設定',
          picture: userInfo.picture
        });
        setView('home');
      } catch (error) {
        console.error('Google UserInfo Fetch Error:', error);
        alert('ログイン情報の取得に失敗しました。');
      }
    },
    onError: (error) => {
      console.error('Login Failed:', error);
      alert(`Googleログインに失敗しました。オリジン設定を確認してください。`);
    },
  });

  const handleInputChange = (field: keyof typeof postForm, value: string) => {
    setPostForm(prev => ({ ...prev, [field]: value }));
    setIsAIApproved(false);
    setAiAnalysis(null);
  };

  const handlePostSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!isAIApproved) return;

    const finalCategory = postForm.category || aiAnalysis?.detectedCategory || "その他";
    const newId = proposals.length > 0 ? Math.max(...proposals.map(p => p.id)) + 1 : 1;
    const newProposal: Proposal = {
      id: newId,
      title: postForm.title,
      content: postForm.content,
      category: finalCategory,
      status: '受付中',
      adminResponse: '',
      timestamp: new Date().toISOString(),
      signatures: []
    };
    const updated = [newProposal, ...proposals];
    setProposals(updated);
    localStorage.setItem('schoolProposals', JSON.stringify(updated));
    setPostForm({ title: '', content: '', category: '' });
    setAiAnalysis(null);
    setIsAIApproved(false);
    setIsPostModalOpen(false);
  };

  const handleAIAnalyze = async () => {
    if (!postForm.title || !postForm.content) {
        alert("タイトルと内容を入力してください。");
        return;
    }
    setAiAnalysis({ advice: '', loading: true });
    setIsAIApproved(false);

    const result = await analyzeProposal(postForm.title, postForm.content);

    setAiAnalysis({ 
        advice: result.advice || '', 
        loading: false,
        detectedCategory: result.category,
        detectedTags: result.tags
    });
    setIsAIApproved(result.isAppropriate);

    if (result.isAppropriate) {
        setPostForm(prev => ({ 
            ...prev, 
            title: result.refinedTitle || prev.title,
            content: result.refinedContent || prev.content,
            category: result.category || prev.category
        }));
    }
  };

  const toggleSignature = (proposalId: number) => {
    if (!user) {
      if(confirm('賛同するにはログインが必要です。ログイン画面に移動しますか？')) setView('login');
      return;
    }
    const updated = proposals.map(p => {
      if (p.id === proposalId) {
        const signedIndex = p.signatures.findIndex(s => s.userId === user.id);
        if (signedIndex >= 0) {
          const newSigs = [...p.signatures];
          newSigs.splice(signedIndex, 1);
          return { ...p, signatures: newSigs };
        } else {
          return { ...p, signatures: [...p.signatures, { userId: user.id, userName: user.name, timestamp: new Date().toISOString() }] };
        }
      }
      return p;
    });
    setProposals(updated);
    localStorage.setItem('schoolProposals', JSON.stringify(updated));
  };

  const filteredProposals = useMemo(() => {
    let res = [...proposals];
    if (categoryFilter !== 'all') res = res.filter(p => p.category === categoryFilter);
    if (searchTerm) {
      const lower = searchTerm.toLowerCase();
      res = res.filter(p => p.title.toLowerCase().includes(lower) || p.content.toLowerCase().includes(lower));
    }
    if (sortOrder === 'newest') res.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
    else res.sort((a, b) => b.signatures.length - a.signatures.length);
    return res;
  }, [proposals, categoryFilter, searchTerm, sortOrder]);

  const trendingTags = useMemo(() => {
      const counts: Record<string, number> = {};
      proposals.forEach(p => {
          const tags = p.content.match(/([#＃][^\s　]+)/g);
          if (tags) tags.forEach(t => counts[t] = (counts[t] || 0) + 1);
      });
      return Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 5);
  }, [proposals]);

  const selectedProposal = useMemo(() => proposals.find(p => p.id === selectedProposalId), [proposals, selectedProposalId]);

  // --- Render Sections ---

  const renderSidebar = () => (
    <aside className="bg-primary-dark text-white p-5 flex flex-col h-screen sticky top-0 z-50 shadow-xl">
      <div className="flex items-center gap-3 mb-10">
        <span className="material-icons-round text-accent text-4xl">school</span>
        <h1 className="text-2xl font-extrabold tracking-wide">ProPoSal</h1>
      </div>

      <nav className="flex flex-col gap-2">
        <button onClick={() => setView('home')} className={`flex items-center gap-4 px-4 py-3 rounded-lg font-bold transition-all ${view === 'home' ? 'bg-white/20 border-l-4 border-accent' : 'text-white/70 hover:bg-white/10'}`}>
          <span className="material-icons-round">home</span>ホーム
        </button>
        <button onClick={() => setView('proposals')} className={`flex items-center gap-4 px-4 py-3 rounded-lg font-bold transition-all ${view === 'proposals' ? 'bg-white/20 border-l-4 border-accent' : 'text-white/70 hover:bg-white/10'}`}>
          <span className="material-icons-round">campaign</span>意見ボックス
        </button>
        <button onClick={() => setView('status')} className={`flex items-center gap-4 px-4 py-3 rounded-lg font-bold transition-all ${view === 'status' ? 'bg-white/20 border-l-4 border-accent' : 'text-white/70 hover:bg-white/10'}`}>
          <span className="material-icons-round">trending_up</span>進捗状況
        </button>
        <button onClick={() => setTheme(prev => prev === 'light' ? 'dark' : 'light')} className="flex items-center gap-4 px-4 py-3 rounded-lg hover:bg-white/10 text-white/70 font-bold transition-all">
          <span className="material-icons-round">{theme === 'light' ? 'dark_mode' : 'light_mode'}</span>テーマ切替
        </button>
      </nav>

      <div className="space-y-4 mt-8">
        <button onClick={() => setIsPostModalOpen(true)} className="w-full bg-white text-primary-dark font-bold py-3 rounded-lg shadow-lg flex items-center justify-center gap-2 hover:-translate-y-1 transition-transform border-2 border-accent">
            <span>意見を投稿する</span><span className="material-icons-round">edit</span>
        </button>
      </div>

      <div className="mt-auto pt-6 border-t border-white/20">
        {user ? (
           <div className="flex items-center gap-3">
             {user.picture ? (
                 <img src={user.picture} alt="" className="w-10 h-10 rounded-full border-2 border-white" />
             ) : (
                 <div className="w-10 h-10 bg-white text-primary-dark rounded-full flex items-center justify-center font-bold text-lg">{user.name.charAt(0)}</div>
             )}
             <div className="flex-1 min-w-0">
               <div className="font-bold truncate">{user.name}</div>
               <div className="text-xs text-white/70 truncate">{user.class}</div>
             </div>
             <button onClick={() => setUser(null)} className="text-white/70 hover:text-white"><span className="material-icons-round">logout</span></button>
           </div>
        ) : (
          <button onClick={() => loginWithGoogle()} className="w-full bg-white/10 rounded-lg py-2 flex items-center justify-center gap-2 hover:bg-white/20 transition-colors text-white font-bold border border-white/30">
            <span className="material-icons-round">login</span>Googleログイン
          </button>
        )}
      </div>
    </aside>
  );

  const renderHomeView = () => (
    <div className="p-6">
      <div className="bg-gradient-to-br from-primary to-primary-light rounded-2xl p-8 text-white shadow-xl mb-8 text-center">
        <h2 className="text-3xl font-extrabold mb-4">テクノロジーで、<br/>学校は変えられる。</h2>
        <p className="text-lg opacity-90">ProPoSalは、生徒一人ひとりの意見を可視化し、<br/>民主的な学校づくりを実現するプラットフォームです。</p>
      </div>

      <section className="mb-10">
        <h3 className="text-sm font-bold text-gray-500 mb-4 border-b pb-2">💡 ルール</h3>
        <div className="grid md:grid-cols-3 gap-4">
          <div className="bg-bg-card dark:bg-bg-cardDark p-6 rounded-xl border-l-8 border-accent shadow-sm">
            <h4 className="font-bold text-primary dark:text-primary-light mb-2">1. 匿名投稿</h4>
            <p className="text-sm opacity-80">投稿者は完全に隠されます。安心して本音を投稿してください。</p>
          </div>
          <div className="bg-bg-card dark:bg-bg-cardDark p-6 rounded-xl border-l-8 border-accent shadow-sm">
            <h4 className="font-bold text-primary dark:text-primary-light mb-2">2. 実名賛同</h4>
            <p className="text-sm opacity-80">賛同にはログインが必要。信頼性と説得力を高めます。</p>
          </div>
           <div className="bg-bg-card dark:bg-bg-cardDark p-6 rounded-xl border-l-8 border-accent shadow-sm">
            <h4 className="font-bold text-primary dark:text-primary-light mb-2">3. 透明な進捗</h4>
            <p className="text-sm opacity-80">意見がどう扱われているかリアルタイムで可視化されます。</p>
          </div>
        </div>
      </section>
    </div>
