              <div className="bg-white rounded-2xl shadow-xl w-full max-w-md p-8 text-center">
                  <h1 className="text-3xl font-bold text-primary mb-6">ProPoSal</h1>
                  <button onClick={() => loginWithGoogle()} className="w-full bg-white text-gray-700 font-bold py-3 rounded-lg border border-gray-300 shadow-sm hover:bg-gray-50 transition-colors flex items-center justify-center gap-3 mb-4">
                      <img src="https://www.svgrepo.com/show/475656/google-color.svg" className="w-5 h-5" alt="" />
