  return (
    <div className="min-h-screen grid grid-cols-1 md:grid-cols-[260px_1fr] lg:grid-cols-[260px_1fr_300px] font-sans">
      {renderSidebar()}
      <main className="bg-bg-body dark:bg-bg-dark border-r border-gray-200 dark:border-gray-800 h-screen overflow-y-auto">
