        {view === 'home' && renderHomeView()}
        {view === 'proposals' && (
            <div className="p-6">
                <div className="space-y-4">
                    {filteredProposals.map(p => (
                        <div key={p.id} onClick={() => setSelectedProposalId(p.id)} className="bg-bg-card dark:bg-bg-cardDark p-6 rounded-xl shadow-sm border-t-4 border-primary hover:border-primary-light cursor-pointer transition-all">
                            <div className="flex justify-between items-start mb-2">
                                <h3 className="font-bold text-lg dark:text-white">{p.title}</h3>
                                <StatusBadge status={p.status} />
                            </div>
                            <p className="text-sm opacity-70 mb-4 line-clamp-2">{p.content}</p>
                            <div className="flex justify-between items-center text-xs opacity-60">
                                <span>{p.category} · {new Date(p.timestamp).toLocaleDateString()}</span>
                                <span className="flex items-center gap-1 font-bold"><span className="material-icons-round text-sm">thumb_up</span>{p.signatures.length}</span>
