                        <div className="flex justify-between items-center mb-4">
                            <StatusBadge status={status} />
                            <span className="text-xs font-bold opacity-50">{proposals.filter(p => p.status === status).length}</span>
                        </div>
                        <div className="space-y-3 overflow-y-auto">
                            {proposals.filter(p => p.status === status).map(p => (
                                <div key={p.id} onClick={() => setSelectedProposalId(p.id)} className="bg-white dark:bg-bg-cardDark p-3 rounded-lg shadow-sm cursor-pointer border hover:border-primary">
                                    <div className="text-xs opacity-50 mb-1">{p.category}</div>
                                    <h4 className="text-sm font-bold line-clamp-2">{p.title}</h4>
                                </div>
                            ))}
                        </div>
                    </div>
                ))}
            </div>
        )}
      </main>

      <aside className="bg-bg-body dark:bg-bg-dark hidden lg:block p-5 h-screen sticky top-0">
