            <input type="text" placeholder="検索..." className="bg-transparent outline-none w-full text-sm dark:text-white" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
        </div>
        <div className="bg-bg-card dark:bg-bg-cardDark rounded-xl p-5 shadow-sm mb-6">
            <h3 className="font-bold text-sm text-primary mb-4">急上昇ワード</h3>
            <div className="flex flex-wrap gap-2">
                {trendingTags.map(([tag, count]) => (
                    <button key={tag} onClick={() => { setSearchTerm(tag); setView('proposals'); }} className="bg-gray-100 dark:bg-gray-700 text-xs px-3 py-1 rounded-full">{tag}({count})</button>
                ))}
            </div>
        </div>
      </aside>

      {/* --- Modals --- */}
      {isPostModalOpen && (
        <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-white dark:bg-bg-cardDark w-full max-w-2xl rounded-2xl shadow-2xl flex flex-col max-h-[90vh]">
                <div className="bg-primary text-white p-4 rounded-t-2xl flex justify-between items-center">
                    <h2 className="font-bold flex items-center gap-2"><span className="material-icons-round">edit</span> 意見を投稿する</h2>
                    <button onClick={() => setIsPostModalOpen(false)}><span className="material-icons-round">close</span></button>
                </div>
                <form onSubmit={handlePostSubmit} className="flex-1 overflow-y-auto p-6 flex flex-col gap-4">
                    <input type="text" placeholder="タイトル" className="text-xl font-bold border-b p-2 outline-none bg-transparent dark:text-white" value={postForm.title} onChange={e => handleInputChange('title', e.target.value)} required />
                    <textarea placeholder="内容を入力してください..." className="flex-1 min-h-[200px] p-4 bg-gray-50 dark:bg-gray-800 rounded-lg outline-none dark:text-white" value={postForm.content} onChange={e => handleInputChange('content', e.target.value)} required />

                    <div className={`p-5 rounded-xl border-2 ${isAIApproved ? 'bg-green-50 border-green-500' : 'bg-blue-50 border-blue-200'} dark:bg-black/20`}>
                        <div className="flex justify-between items-center mb-3">
                            <h4 className="font-bold flex items-center gap-2">AIチェック {isAIApproved && '✅'}</h4>
                            <button type="button" onClick={handleAIAnalyze} disabled={aiAnalysis?.loading} className="bg-blue-600 text-white px-4 py-2 rounded-full text-xs font-bold disabled:opacity-50">
                                {aiAnalysis?.loading ? '分析中...' : 'AIチェック実行'}
                            </button>
                        </div>
                        {aiAnalysis && <p className="text-sm opacity-80 mb-2">{aiAnalysis.advice}</p>}
                        {isAIApproved && (
                            <div className="flex flex-wrap gap-2">
                                <span className="text-xs bg-green-100 text-green-800 px-2 py-1 rounded font-bold">{aiAnalysis?.detectedCategory}</span>
                                {aiAnalysis?.detectedTags?.map(t => <span key={t} className="text-xs bg-blue-100 text-blue-800 px-2 py-1 rounded">{t}</span>)}
                            </div>
                        )}
                    </div>
                    {isAIApproved && <button type="submit" className="bg-primary text-white font-bold py-3 px-8 rounded-full shadow-lg">投稿する</button>}
                </form>
            </div>
        </div>
      )}

      {selectedProposal && (
          <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
              <div className="bg-white dark:bg-bg-cardDark w-full max-w-2xl rounded-2xl shadow-2xl flex flex-col max-h-[90vh]">
                  <div className="bg-primary text-white p-4 flex justify-between items-center">
                      <h2 className="font-bold truncate">{selectedProposal.title}</h2>
                      <button onClick={() => setSelectedProposalId(null)}><span className="material-icons-round">close</span></button>
                  </div>
                  <div className="p-6 overflow-y-auto">
                      <div className="flex gap-2 mb-4"><StatusBadge status={selectedProposal.status} /> <span className="opacity-50 text-sm">{selectedProposal.category}</span></div>
                      <div className="text-lg mb-8 whitespace-pre-wrap">{selectedProposal.content}</div>
                      <div className="flex justify-between items-center pt-6 border-t">
                        <div className="text-2xl font-bold text-primary">賛同数: {selectedProposal.signatures.length}</div>
                        <button onClick={() => toggleSignature(selectedProposal.id)} className={`px-8 py-3 rounded-full font-bold shadow-md transition-all ${user && selectedProposal.signatures.some(s => s.userId === user.id) ? 'bg-pink-100 text-pink-600' : 'bg-primary text-white'}`}>
                            {user && selectedProposal.signatures.some(s => s.userId === user.id) ? '✅ 賛同済み' : '👍 賛同する'}
                        </button>
                      </div>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

