import { GoogleGenAI, Type } from "@google/genai";

export interface AIAnalysisResult {
  isAppropriate: boolean;
  category: string;
  tags: string[];
  refinedTitle?: string;
  refinedContent?: string;
  advice?: string;
}

const SCHOOL_RULES = `
【現在の校則・きまり】
1. 服装: 指定の制服を着用。靴下は白・黒・紺の無地のみ（グレーは不可）。
2. 頭髪: 染髪・パーマ禁止。肩に付く場合は結ぶ。
3. 持ち物: スマホは原則持ち込み禁止（特別な事情がある場合のみ許可制）。
4. 学校生活: 8:30までに登校。アルバイトは原則禁止。
5. 設備: 体育館のボール貸出は昼休みのみ。図書室は17:00閉館。
`;

export const analyzeProposal = async (title: string, content: string): Promise<AIAnalysisResult> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const systemPrompt = `
      あなたは中学校の「デジタル目安箱」の専属AIアドバイザーです。
      生徒が投稿しようとしている意見を分析し、以下のガイドラインに従ってフィードバックを行ってください。

      【校則データ】
      ${SCHOOL_RULES}

      【あなたのミッション】
      1. カテゴリー分類: 「校則」「設備・環境」「授業」「その他」から選択。
      2. タグ生成: 関連するハッシュタグ（#付き）を3個程度。
      3. 適切性判定:
         - 「校則を変えたい」という提案（例：靴下の色を自由にしてほしい、スマホを持ち込みたい）は、建設的な内容であれば『適切(true)』です。
         - 誹謗中傷、個人名を出した攻撃、明らかな暴言、意味不明な投稿は『不適切(false)』です。
      4. ブラッシュアップ:
         - 適切な場合: 敬語への修正や、理由の補強を行い、説得力を高めた文章を作成してください。
         - 不適切な場合: なぜ不適切かを優しく諭し、どう書き直すべきかアドバイスしてください。
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `タイトル: ${title}\n内容: ${content}`,
      config: {
        systemInstruction: systemPrompt,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            isAppropriate: { type: Type.BOOLEAN },
            category: { type: Type.STRING },
            tags: { type: Type.ARRAY, items: { type: Type.STRING } },
            refinedTitle: { type: Type.STRING },
            refinedContent: { type: Type.STRING },
            advice: { type: Type.STRING },
          },
          required: ["isAppropriate", "category", "tags", "refinedTitle", "refinedContent", "advice"],
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("AIからの応答が空です");
    return JSON.parse(text) as AIAnalysisResult;

  } catch (error) {
    console.error("AI Analysis Error:", error);
    return {
      isAppropriate: false,
      category: "その他",
      tags: [],
      advice: "現在AIチェックが混み合っています。少し時間をおいてから試してみてください。"
    };
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { analyzeProposal, AIAnalysisResult } from './services/geminiService';
import { useGoogleLogin } from '@react-oauth/google';

// --- Types ---
interface User {
  id: string;
  name: string;
  role: 'student' | 'admin';
  class?: string;
  picture?: string;
}

interface Signature {
  userId: string;
  userName: string;
  timestamp: string;
}

interface Proposal {
  id: number;
  title: string;
  content: string;
  category: string;
  status: '受付中' | '検討中' | '先生と調整中' | '対応済';
  adminResponse: string;
  timestamp: string;
  signatures: Signature[];
}

// --- Constants ---
const STATUS_STEPS = ['受付中', '検討中', '先生と調整中', '対応済'];
const CATEGORIES = ['校則', '設備・環境', '授業', 'その他'];

// --- Helper Components ---
const StatusBadge: React.FC<{ status: string }> = ({ status }) => {
  const colors: Record<string, string> = {
    '受付中': 'bg-blue-100 text-blue-800 dark:bg-blue-900/40 dark:text-blue-200',
    '検討中': 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/40 dark:text-yellow-200',
    '先生と調整中': 'bg-purple-100 text-purple-800 dark:bg-purple-900/40 dark:text-purple-200',
    '対応済': 'bg-green-100 text-green-800 dark:bg-green-900/40 dark:text-green-200',
  };
  return (
    <span className={`px-2.5 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider ${colors[status] || 'bg-gray-100 text-gray-800'}`}>
      {status}
    </span>
  );
};

// --- Main Component ---
const App: React.FC = () => {
