                 <button onClick={() => setIsPostModalOpen(false)} className="w-10 h-10 rounded-full hover:bg-white/20 flex items-center justify-center transition-colors">
                    <span className="material-icons-round">close</span>
                 </button>
              </div>
              <div className="flex-1 overflow-y-auto p-8 space-y-6">
                 <input 
                  type="text" 
                  placeholder="タイトルを入力（例：体育館のボールについて）" 
