                 <div className={`p-8 rounded-[2rem] border-2 transition-all duration-500 ${isAIApproved ? 'bg-green-50 border-green-200 dark:bg-green-900/10' : aiResult.result ? 'bg-red-50 border-red-200 dark:bg-red-900/10' : 'bg-primary/5 border-primary/10'}`}>
                    <div className="flex justify-between items-center mb-4">
                       <h4 className="font-bold flex items-center gap-2">
                          <span className="material-icons-round text-primary">{aiResult.loading ? 'refresh' : 'psychology'}</span>
