                       </h4>
                       {!isAIApproved && (
                        <button 
                          onClick={handleAIAnalyze} 
                          disabled={aiResult.loading}
                          className="bg-primary text-white px-8 py-3 rounded-full text-xs font-black hover:scale-105 transition-all shadow-lg shadow-primary/30 disabled:opacity-50"
                        >
                          {aiResult.loading ? '分析中...' : 'チェックを実行'}
