  const [categoryFilter, setCategoryFilter] = useState('all');

  // Auth Forms
  const [authForm, setAuthForm] = useState({ name: '', email: '', password: '', confirmPassword: '', role: 'student', class: '' });

  // Proposal Form
  const [postForm, setPostForm] = useState({ title: '', content: '' });
  const [approvedPostForm, setApprovedPostForm] = useState({ title: '', content: '' });
  const [aiResult, setAiResult] = useState<{ loading: boolean; result: AIAnalysisResult | null }>({ loading: false, result: null });
  const [isAIApproved, setIsAIApproved] = useState(false);

  // Admin Controls
  const [adminEditId, setAdminEditId] = useState<number | null>(null);
  const [adminResponseText, setAdminResponseText] = useState('');
  const [adminStatusSelect, setAdminStatusSelect] = useState<Proposal['status']>('受付中');

  // --- Effects ---
  useEffect(() => {
    const saved = localStorage.getItem('schoolProposals');
    if (saved) setProposals(JSON.parse(saved));
    else {
      const seeds: Proposal[] = [
        { id: 1, title: '靴下の色を自由にしたい', content: '現在は黒白紺のみですが、グレーも許可してほしいです。', category: '校則', status: '先生と調整中', adminResponse: '校長Tと交渉中。検討を重ねています。', timestamp: new Date().toISOString(), signatures: [] },
        { id: 2, title: '図書室の開館時間延長', content: '放課後もっと勉強したいです。', category: '設備・環境', status: '受付中', adminResponse: '', timestamp: new Date().toISOString(), signatures: [] },
      ];
      setProposals(seeds);
      localStorage.setItem('schoolProposals', JSON.stringify(seeds));
    }

    const savedMyIds = localStorage.getItem('myProposalIds');
    if (savedMyIds) setMyProposalIds(JSON.parse(savedMyIds));

    const savedTheme = localStorage.getItem('theme') as 'light' | 'dark';
    if (savedTheme) setTheme(savedTheme);
  }, []);

  useEffect(() => {
    document.documentElement.classList.toggle('dark', theme === 'dark');
    localStorage.setItem('theme', theme);
  }, [theme]);

  // AI re-validation check
  useEffect(() => {
    if (isAIApproved && (postForm.title !== approvedPostForm.title || postForm.content !== approvedPostForm.content)) {
      setIsAIApproved(false);
      setAiResult({ loading: false, result: null });
    }
  }, [postForm, isAIApproved, approvedPostForm]);

  // --- Handlers ---
  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (!authForm.email || !authForm.password) return alert("情報を入力してください");

    const isSpecialAdmin = authForm.email === ADMIN_EMAIL;
    setUser({ 
      id: authForm.email, 
      email: authForm.email, 
      name: isSpecialAdmin ? '生徒会管理者' : authForm.email.split('@')[0], 
      role: isSpecialAdmin ? 'admin' : 'student' 
    });
    setView(isSpecialAdmin ? 'admin' : 'home');
  };

  const handleRegister = (e: React.FormEvent) => {
    e.preventDefault();
    if (authForm.password !== authForm.confirmPassword) return alert("パスワードが一致しません");
    setUser({ id: authForm.email, email: authForm.email, name: authForm.name, role: authForm.role as any, class: authForm.class });
    setView('home');
  };

  const handleAIAnalyze = async () => {
    if (!postForm.title || !postForm.content) return alert("タイトルと内容を入力してください");
    setAiResult({ loading: true, result: null });
    const result = await analyzeProposal(postForm.title, postForm.content);
    setAiResult({ loading: false, result });

    if (result.isAppropriate) {
        const finalTitle = result.refinedTitle || postForm.title;
        const finalContent = result.refinedContent || postForm.content;
        setPostForm({ title: finalTitle, content: finalContent });
        setApprovedPostForm({ title: finalTitle, content: finalContent });
        setIsAIApproved(true);
    } else {
        setIsAIApproved(false);
    }
  };

  const handlePostSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!isAIApproved || !aiResult.result) return;
    const newId = Date.now();
    const newProposal: Proposal = {
      id: newId,
      title: postForm.title,
      content: postForm.content,
      category: aiResult.result.category,
      status: '受付中',
      adminResponse: '',
      timestamp: new Date().toISOString(),
      signatures: []
    };
    const updated = [newProposal, ...proposals];
    setProposals(updated);
    localStorage.setItem('schoolProposals', JSON.stringify(updated));

    const updatedMyIds = [...myProposalIds, newId];
    setMyProposalIds(updatedMyIds);
    localStorage.setItem('myProposalIds', JSON.stringify(updatedMyIds));

    setIsPostModalOpen(false);
    setPostForm({ title: '', content: '' });
    setApprovedPostForm({ title: '', content: '' });
    setAiResult({ loading: false, result: null });
    setIsAIApproved(false);
  };

  const handleDeleteProposal = (id: number) => {
    if (!window.confirm("本当にこの意見を削除しますか？")) return;
    const updated = proposals.filter(p => p.id !== id);
    setProposals(updated);
    localStorage.setItem('schoolProposals', JSON.stringify(updated));
    setMyProposalIds(myProposalIds.filter(mid => mid !== id));
    setSelectedProposalId(null);
  };

  const toggleSignature = (id: number) => {
    if (!user) return alert("賛同するにはログインが必要です");
    const updated = proposals.map(p => {
      if (p.id === id) {
        const index = p.signatures.findIndex(s => s.userId === user.id);
        const newSigs = [...p.signatures];
        if (index >= 0) newSigs.splice(index, 1);
        else newSigs.push({ userId: user.id, userName: user.name, timestamp: new Date().toISOString() });
        return { ...p, signatures: newSigs };
      }
      return p;
    });
    setProposals(updated);
    localStorage.setItem('schoolProposals', JSON.stringify(updated));
  };

  const handleAdminUpdate = () => {
    if (!adminEditId) return;
    const updated = proposals.map(p => {
      if (p.id === adminEditId) {
        return { ...p, status: adminStatusSelect, adminResponse: adminResponseText };
      }
      return p;
    });
    setProposals(updated);
    localStorage.setItem('schoolProposals', JSON.stringify(updated));
    setAdminEditId(null);
  };

  // --- Derived ---
  const filteredProposals = useMemo(() => {
    return proposals.filter(p => {
      const matchSearch = p.title.includes(searchTerm) || p.content.includes(searchTerm);
      const matchCat = categoryFilter === 'all' || p.category === categoryFilter;
      return matchSearch && matchCat;
    });
  }, [proposals, searchTerm, categoryFilter]);

  const trendingTags = useMemo(() => {
    const counts: Record<string, number> = {};
    proposals.forEach(p => {
      const tags = p.content.match(/#\w+/g);
      if (tags) tags.forEach(t => counts[t] = (counts[t] || 0) + 1);
    });
    return Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 5);
  }, [proposals]);

  // --- Auth Screen ---
  if (!user && (view === 'login' || view === 'register')) {
    return (
      <div className="min-h-screen bg-[#f9f7fa] flex flex-col items-center justify-center p-6 font-sans">
        <div className="mb-10 text-center">
           <div className="flex items-center justify-center gap-2 mb-2">
              <span className="material-icons-round text-[#9d46ff] text-4xl">auto_awesome</span>
              <h1 className="text-4xl font-black text-[#6a0dad]">ProPoSal</h1>
           </div>
           <p className="text-gray-500 font-medium">デジタル校内民主主義プロジェクト</p>
        </div>

        <div className="w-full max-w-md bg-white rounded-[2rem] shadow-xl p-8">
           <div className="flex bg-gray-100 p-1.5 rounded-2xl mb-8">
              <button 
                onClick={() => setView('login')}
                className={`flex-1 py-3 rounded-xl font-bold transition-all ${view === 'login' ? 'bg-white shadow-sm text-black' : 'text-gray-400'}`}
              >ログイン</button>
              <button 
                onClick={() => setView('register')}
                className={`flex-1 py-3 rounded-xl font-bold transition-all ${view === 'register' ? 'bg-white shadow-sm text-black' : 'text-gray-400'}`}
              >新規登録</button>
           </div>

           {view === 'login' ? (
             <form onSubmit={handleLogin} className="space-y-6">
                <div>
                   <label className="block text-sm font-bold mb-2 ml-1">メールアドレス</label>
                   <input 
                    type="email" 
                    placeholder="example@toda-jhs.ed.jp" 
                    className="w-full bg-gray-50 border-none rounded-xl p-4 outline-none focus:ring-2 ring-primary/20"
                    value={authForm.email}
                    onChange={e => setAuthForm({...authForm, email: e.target.value})}
                  />
                </div>
                <div>
                   <label className="block text-sm font-bold mb-2 ml-1">パスワード</label>
                   <input 
                    type="password" 
                    className="w-full bg-gray-50 border-none rounded-xl p-4 outline-none focus:ring-2 ring-primary/20"
                    value={authForm.password}
                    onChange={e => setAuthForm({...authForm, password: e.target.value})}
                  />
                </div>
                <button type="submit" className="w-full bg-[#0d0d12] text-white font-black py-4 rounded-xl shadow-lg hover:bg-black transition-colors">Log in</button>
             </form>
           ) : (
             <form onSubmit={handleRegister} className="space-y-4">
                <div>
                   <label className="block text-sm font-bold mb-1 ml-1">本名</label>
                   <input type="text" placeholder="山田 太郎" className="w-full bg-gray-50 border-none rounded-xl p-3 outline-none" value={authForm.name} onChange={e => setAuthForm({...authForm, name: e.target.value})} />
                </div>
                <div>
                   <label className="block text-sm font-bold mb-1 ml-1">メールアドレス</label>
                   <input type="email" placeholder="example@toda-jhs.ed.jp" className="w-full bg-gray-50 border-none rounded-xl p-3 outline-none" value={authForm.email} onChange={e => setAuthForm({...authForm, email: e.target.value})} />
                </div>
                <div>
                   <label className="block text-sm font-bold mb-1 ml-1">パスワード</label>
                   <input type="password" placeholder="••••••••" className="w-full bg-gray-50 border-none rounded-xl p-3 outline-none" value={authForm.password} onChange={e => setAuthForm({...authForm, password: e.target.value})} />
                </div>
                <div>
                   <label className="block text-sm font-bold mb-1 ml-1">パスワード確認</label>
                   <input type="password" placeholder="••••••••" className="w-full bg-gray-50 border-none rounded-xl p-3 outline-none" value={authForm.confirmPassword} onChange={e => setAuthForm({...authForm, confirmPassword: e.target.value})} />
                </div>
                <div className="grid grid-cols-2 gap-3">
                   <div>
                      <label className="block text-sm font-bold mb-1 ml-1">役割</label>
                      <select className="w-full bg-gray-50 border-none rounded-xl p-3 outline-none appearance-none" value={authForm.role} onChange={e => setAuthForm({...authForm, role: e.target.value as any})}>
                         <option value="student">生徒</option>
                         <option value="teacher">先生</option>
                      </select>
                   </div>
                   <div>
                      <label className="block text-sm font-bold mb-1 ml-1">クラス</label>
                      <input type="text" placeholder="3年A組" className="w-full bg-gray-50 border-none rounded-xl p-3 outline-none" value={authForm.class} onChange={e => setAuthForm({...authForm, class: e.target.value})} />
                   </div>
                </div>
                <button type="submit" className="w-full bg-[#0d0d12] text-white font-black py-4 rounded-xl mt-4 shadow-lg">アカウント作成</button>
             </form>
           )}
        </div>

        <button 
          onClick={() => {setUser(null); setView('home');}}
          className="mt-6 w-full max-w-md bg-white/60 border border-gray-200 text-gray-700 py-3 rounded-xl font-bold flex items-center justify-center gap-2 hover:bg-white transition-all"
        >
          <span className="material-icons-round">home</span>
          Homeに戻る
        </button>

        <div className="mt-10 text-gray-400 text-sm font-medium">
          戸田市立戸田中学校 生徒会
        </div>
      </div>
    );
  }

  // --- Main Render ---
  return (
    <div className="min-h-screen grid grid-cols-1 md:grid-cols-[240px_1fr] lg:grid-cols-[240px_1fr_300px]">

      {/* Sidebar */}
      <aside className="bg-primary-dark text-white p-6 flex flex-col gap-8 h-screen sticky top-0 z-50 shadow-2xl">
        <div className="flex items-center gap-3">
          <span className="material-icons-round text-accent text-3xl">school</span>
          <h1 className="text-xl font-black tracking-tighter">ProPoSal</h1>
        </div>

        <nav className="flex flex-col gap-1">
          {[
            { id: 'home', icon: 'home', label: 'Home' },
            { id: 'proposals', icon: 'campaign', label: '意見ボックス' },
            { id: 'status', icon: 'trending_up', label: '進捗・ステータス' }
          ].map(item => (
            <button 
              key={item.id}
              onClick={() => setView(item.id as any)}
              className={`flex items-center gap-4 px-4 py-3 rounded-xl font-bold transition-all ${view === item.id ? 'bg-white/20 border-l-4 border-accent' : 'hover:bg-white/10 opacity-70 hover:opacity-100'}`}
            >
              <span className="material-icons-round">{item.icon}</span>
              {item.label}
            </button>
          ))}
          {user?.role === 'admin' && (
            <button 
              onClick={() => setView('admin')}
              className={`flex items-center gap-4 px-4 py-3 rounded-xl font-bold transition-all ${view === 'admin' ? 'bg-white/20 border-l-4 border-accent' : 'hover:bg-white/10 opacity-70 hover:opacity-100'}`}
            >
              <span className="material-icons-round">admin_panel_settings</span>
              生徒会管理
            </button>
          )}
        </nav>

        <div className="flex flex-col gap-3 mt-4">
          <button onClick={() => setIsPostModalOpen(true)} className="bg-accent text-primary-dark font-black py-4 rounded-2xl shadow-xl hover:scale-105 transition-transform flex items-center justify-center gap-2">
            <span className="material-icons-round">edit</span>
            意見を投稿する
          </button>
          <button onClick={() => setView('proposals')} className="bg-white/10 text-white font-black py-4 rounded-2xl border border-white/20 hover:bg-white/20 transition-all flex items-center justify-center gap-2">
            <span className="material-icons-round">visibility</span>
            意見を見に行く
          </button>
        </div>

        <div className="mt-auto pt-6 border-t border-white/10">
          {user ? (
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-white text-primary-dark rounded-full flex items-center justify-center font-bold uppercase">{user.name.charAt(0)}</div>
              <div className="flex-1 min-w-0">
                <div className="font-bold text-sm truncate">{user.name}</div>
                <div className="text-[10px] opacity-50 uppercase tracking-widest">{user.role}</div>
              </div>
              <button onClick={() => {setUser(null); setView('home');}}><span className="material-icons-round text-lg">logout</span></button>
            </div>
          ) : (
            <button onClick={() => setView('login')} className="w-full bg-white/10 py-3 rounded-xl border border-white/20 flex items-center justify-center gap-2">
              <span className="material-icons-round">login</span>
              Log in
            </button>
          )}
        </div>
      </aside>

      {/* Main Content */}
      <main className="bg-bg-body dark:bg-bg-dark overflow-y-auto">
        <header className="px-8 py-6 flex justify-between items-center sticky top-0 bg-bg-body/80 dark:bg-bg-dark/80 backdrop-blur-md z-40">
           <h2 className="text-2xl font-black text-primary-dark dark:text-white capitalize tracking-tight">
             {view === 'home' ? 'Home' : view === 'proposals' ? '意見ボックス' : view === 'status' ? '進捗・ステータス' : '生徒会管理'}
           </h2>
           <button onClick={() => setTheme(t => t === 'light' ? 'dark' : 'light')} className="w-10 h-10 rounded-full bg-white dark:bg-gray-800 shadow-sm flex items-center justify-center transition-transform hover:scale-110">
              <span className="material-icons-round text-lg">{theme === 'light' ? 'dark_mode' : 'light_mode'}</span>
           </button>
        </header>

        <div className="px-8 pb-12">
          {view === 'home' && (
            <div className="space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-700">
               <div className="p-12 rounded-[2rem] bg-gradient-to-br from-primary to-primary-light text-white shadow-2xl relative overflow-hidden text-center">
                  <div className="relative z-10">
                    <h3 className="text-5xl font-black mb-6 leading-tight">テクノロジーで、<br/>学校は変えられる。</h3>
                    <p className="opacity-90 text-xl max-w-2xl mx-auto leading-relaxed">
                      ProPoSalは、生徒一人ひとりの意見を可視化し、<br/>民主的な学校づくりを実現するプラットフォームです。
                    </p>
                  </div>
                  <span className="material-icons-round absolute -bottom-10 -right-10 text-[240px] opacity-10 rotate-12">auto_awesome</span>
               </div>

               <section>
                 <h4 className="text-sm font-bold text-gray-400 mb-6 flex items-center gap-2 uppercase tracking-widest">
                   <span className="material-icons-round text-sm">lightbulb</span> 仕組みとルール
                 </h4>
                 <div className="flex flex-col gap-6">
                   {[
                     { icon: 'lock', title: '1. 完全匿名での投稿', desc: '意見を投稿する際、誰が書いたかは完全に隠されます。安心して本音を投稿してください。', color: 'border-yellow-400' },
                     { icon: 'verified_user', title: '2. 賛同は「実名」で', desc: '投稿された意見に「いいね（賛同）」する時はログインが必要です。信頼性を担保し、学校側への説得力を高めます。', color: 'border-purple-500' },
                     { icon: 'visibility', title: '3. 透明なプロセス', desc: '集まった賛同数に応じて、ステータスが「受付中→検討中→対応済」と変化します。自分の意見がどう扱われているか、いつでも確認できます。', color: 'border-indigo-500' }
                   ].map((item, i) => (
                     <div key={i} className={`bg-white dark:bg-bg-cardDark p-8 rounded-[1.5rem] shadow-sm border-l-8 ${item.color} hover:shadow-lg hover:translate-x-1 transition-all duration-300`}>
                       <div className="flex items-center gap-4 mb-3">
                         <span className="material-icons-round text-primary-light text-2xl">{item.icon}</span>
                         <h5 className="font-black text-xl text-primary-dark dark:text-primary-light">{item.title}</h5>
                       </div>
                       <p className="text-gray-600 dark:text-gray-400 leading-relaxed pl-10">{item.desc}</p>
                     </div>
                   ))}
                   <div className="mt-4 text-center">
                      <button onClick={() => setView('proposals')} className="px-12 py-5 bg-[#0d0d12] text-white font-black rounded-2xl shadow-xl hover:scale-105 transition-transform flex items-center justify-center gap-3 mx-auto">
                         <span className="material-icons-round">campaign</span>
                         意見を見に行く
                      </button>
                   </div>
                 </div>
               </section>
            </div>
          )}

          {view === 'proposals' && (
            <div className="space-y-4">
              {filteredProposals.length === 0 ? (
                <div className="text-center py-20 opacity-30">
                   <span className="material-icons-round text-6xl block mb-4">search_off</span>
                   意見が見つかりませんでした
                </div>
              ) : (
                filteredProposals.map(p => (
                  <div key={p.id} onClick={() => setSelectedProposalId(p.id)} className="bg-white dark:bg-bg-cardDark p-6 rounded-3xl shadow-sm hover:shadow-xl cursor-pointer transition-all border border-gray-50 dark:border-gray-800 group relative overflow-hidden border-t-4 border-t-primary">
                    <div className="flex justify-between items-start mb-3">
                        <div className="flex gap-2 items-center">
                          <StatusBadge status={p.status} />
                          <span className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{p.category}</span>
                        </div>
                        <div className="flex items-center gap-3">
                          {myProposalIds.includes(p.id) && (
                            <button 
                              onClick={(e) => { e.stopPropagation(); handleDeleteProposal(p.id); }}
                              className="text-gray-300 hover:text-red-500 transition-colors"
                            >
                              <span className="material-icons-round text-lg">delete</span>
                            </button>
                          )}
                          <div className="flex items-center gap-1 text-pink-500 font-black">
                            <span className="material-icons-round text-sm">thumb_up</span>
                            {p.signatures.length}
                          </div>
                        </div>
                    </div>
                    <h4 className="text-xl font-bold mb-2 group-hover:text-primary transition-colors">{p.title}</h4>
                    <p className="text-sm opacity-60 line-clamp-2 leading-relaxed">{p.content}</p>
                    <div className="mt-4 flex items-center gap-2 text-[10px] text-gray-400">
                        <span className="material-icons-round text-[12px]">schedule</span>
                        {new Date(p.timestamp).toLocaleDateString()}
                    </div>
                  </div>
                ))
              )}
            </div>
          )}

          {view === 'status' && (
            <div className="grid lg:grid-cols-4 gap-4 items-start min-h-[60vh]">
               {STATUS_STEPS.map(step => (
                 <div key={step} className="bg-gray-200 dark:bg-white/10 p-5 rounded-3xl flex flex-col gap-4 min-h-[400px] shadow-inner">
                    <div className="flex justify-between items-center px-1">
                       <StatusBadge status={step} />
                       <span className="text-xs font-bold opacity-40">{proposals.filter(p => p.status === step).length}件</span>
                    </div>
                    <div className="space-y-3">
                      {proposals.filter(p => p.status === step).map(p => (
                        <div key={p.id} onClick={() => setSelectedProposalId(p.id)} className="bg-white dark:bg-bg-cardDark p-4 rounded-2xl shadow-sm cursor-pointer border-2 border-transparent hover:border-primary transition-all text-sm font-bold relative group">
                           {myProposalIds.includes(p.id) && (
                              <button 
                                onClick={(e) => { e.stopPropagation(); handleDeleteProposal(p.id); }}
                                className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 text-gray-300 hover:text-red-500 transition-all"
                              >
                                <span className="material-icons-round text-xs">delete</span>
                              </button>
                           )}
                           <div className="text-[10px] opacity-40 mb-1">{p.category}</div>
                           {p.title}
                        </div>
                      ))}
                    </div>
                 </div>
               ))}
            </div>
          )}

          {view === 'admin' && user?.role === 'admin' && (
            <div className="space-y-8 animate-in fade-in duration-500">
              <div className="bg-white dark:bg-bg-cardDark p-8 rounded-[2rem] shadow-sm border border-gray-100 dark:border-gray-800">
                <h3 className="text-xl font-black mb-6 flex items-center gap-2">
                  <span className="material-icons-round text-primary">analytics</span>
                  生徒会管理ダッシュボード
                </h3>

                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead>
                      <tr className="text-xs font-bold text-gray-400 uppercase tracking-widest border-b border-gray-100 dark:border-gray-800">
                        <th className="pb-4 px-2">日時</th>
                        <th className="pb-4 px-2">タイトル</th>
                        <th className="pb-4 px-2">賛同数</th>
                        <th className="pb-4 px-2">ステータス</th>
                        <th className="pb-4 px-2 text-right">アクション</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-50 dark:divide-gray-800">
                      {proposals.map(p => (
                        <tr key={p.id} className="hover:bg-gray-50 dark:hover:bg-gray-800/50 transition-colors">
                          <td className="py-4 px-2 text-xs text-gray-500">{new Date(p.timestamp).toLocaleDateString()}</td>
                          <td className="py-4 px-2 font-bold text-sm">{p.title}</td>
                          <td className="py-4 px-2">
                            <span className="bg-pink-100 text-pink-700 px-2 py-1 rounded-lg text-xs font-black">{p.signatures.length}</span>
                          </td>
                          <td className="py-4 px-2"><StatusBadge status={p.status} /></td>
                          <td className="py-4 px-2 text-right">
                            <button 
                              onClick={() => {
                                setAdminEditId(p.id);
                                setAdminResponseText(p.adminResponse);
                                setAdminStatusSelect(p.status);
                              }}
                              className="bg-primary/10 text-primary hover:bg-primary hover:text-white px-4 py-2 rounded-xl text-xs font-bold transition-all"
                            >
                              編集
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>

      {/* Right Sidebar */}
      <aside className="bg-bg-body dark:bg-bg-dark border-l border-gray-100 dark:border-gray-800 hidden lg:block p-8 space-y-10 overflow-y-auto">
        <div className="bg-white dark:bg-bg-cardDark rounded-3xl p-6 shadow-sm border border-gray-50 dark:border-gray-800">
          <div className="flex items-center gap-2 text-primary font-bold mb-4">
             <span className="material-icons-round text-sm">search</span>
             検索
          </div>
          <input 
            type="text" 
            placeholder="キーワードを入力..." 
            className="w-full bg-gray-50 dark:bg-gray-800 p-4 rounded-2xl text-sm outline-none"
            value={searchTerm}
            onChange={e => setSearchTerm(e.target.value)}
          />
        </div>

        <div>
           <h4 className="text-xs font-bold text-gray-400 mb-4 uppercase tracking-widest flex items-center gap-2">
            <span className="material-icons-round text-sm">folder</span>
            カテゴリー
          </h4>
          <div className="flex flex-wrap gap-2">
            {['all', ...CATEGORIES].map(cat => (
              <button key={cat} onClick={() => {setCategoryFilter(cat); setView('proposals');}} className={`px-4 py-2 rounded-xl text-xs font-bold border transition-all ${categoryFilter === cat ? 'bg-primary text-white border-primary' : 'bg-white dark:bg-bg-cardDark border-gray-100 dark:border-gray-800'}`}>
                {cat === 'all' ? '全て' : cat}
              </button>
            ))}
          </div>
        </div>

        <div>
          <h4 className="text-xs font-bold text-gray-400 mb-4 uppercase tracking-widest flex items-center gap-2">
            <span className="material-icons-round text-sm">local_fire_department</span>
            急上昇ワード
          </h4>
          <div className="flex flex-wrap gap-2">
            {trendingTags.map(([tag, count]) => (
              <button key={tag} onClick={() => {setSearchTerm(tag); setView('proposals');}} className="bg-white dark:bg-bg-cardDark px-4 py-2 rounded-xl text-xs font-bold shadow-sm border border-gray-100 dark:border-gray-800">
                {tag} <span className="opacity-30 ml-1">({count})</span>
              </button>
            ))}
          </div>
        </div>
      </aside>

      {/* Modals */}
      {isPostModalOpen && (
        <div className="fixed inset-0 z-[100] bg-primary-dark/40 backdrop-blur-xl flex items-center justify-center p-4">
           <div className="bg-white dark:bg-bg-cardDark w-full max-w-3xl rounded-[2.5rem] shadow-2xl flex flex-col max-h-[90vh] overflow-hidden">
              <div className="bg-primary text-white p-8 flex justify-between items-center">
                 <h2 className="text-2xl font-black flex items-center gap-3">意見を投稿する</h2>
                 <button onClick={() => setIsPostModalOpen(false)} className="w-10 h-10 rounded-full hover:bg-white/20 flex items-center justify-center"><span className="material-icons-round">close</span></button>
              </div>
              <div className="flex-1 overflow-y-auto p-8 space-y-6">
                 <input 
                  type="text" 
                  placeholder="タイトルを入力..." 
                  className="w-full text-2xl font-black border-b-2 pb-4 outline-none bg-transparent" 
                  value={postForm.title} 
                  onChange={e => setPostForm({...postForm, title: e.target.value})} 
                />
                 <textarea 
                  placeholder="あなたの想いを書いてください..." 
                  className="w-full min-h-[250px] text-lg p-6 bg-gray-50 dark:bg-gray-800 rounded-[2rem] outline-none resize-none" 
                  value={postForm.content} 
                  onChange={e => setPostForm({...postForm, content: e.target.value})} 
                />
                 <div className={`p-8 rounded-[2rem] border-2 transition-all ${isAIApproved ? 'bg-green-50 border-green-200 dark:bg-green-900/10' : aiResult.result ? 'bg-red-50 border-red-200 dark:bg-red-900/10' : 'bg-primary/5 border-primary/10'}`}>
                    <div className="flex justify-between items-center mb-4">
                       <h4 className="font-bold flex items-center gap-2">AIアドバイザー</h4>
                       {(!isAIApproved || (postForm.title !== approvedPostForm.title || postForm.content !== approvedPostForm.content)) && (
                        <button 
                          onClick={handleAIAnalyze} 
                          disabled={aiResult.loading} 
                          className="bg-primary text-white px-8 py-3 rounded-full text-xs font-black shadow-lg disabled:opacity-50"
                        >
                          {aiResult.loading ? '分析中...' : 'チェックを実行'}
                        </button>
                       )}
                    </div>
                    {aiResult.result && (
                      <div>
                        <p className="text-sm leading-relaxed mb-2">{aiResult.result.advice}</p>
                        {isAIApproved && (
                           <div className="flex items-center gap-2 text-[10px] text-green-600 font-bold uppercase tracking-widest">
                              <span className="material-icons-round text-sm">verified</span>
                              チェック完了
                           </div>
                        )}
                      </div>
                    )}
                    {!aiResult.result && !isAIApproved && (
                      <p className="text-xs opacity-40">投稿する前にAIチェックを受ける必要があります。文章を変更すると再チェックが必要です。</p>
                    )}
                 </div>
              </div>
              {isAIApproved && (postForm.title === approvedPostForm.title && postForm.content === approvedPostForm.content) && (
                <div className="p-8 border-t flex justify-end">
                  <button onClick={handlePostSubmit} className="bg-primary text-white font-black px-16 py-4 rounded-[1.5rem] shadow-2xl hover:scale-105 transition-transform">
                    送信する
                  </button>
                </div>
              )}
           </div>
        </div>
      )}

      {selectedProposalId && proposals.find(p => p.id === selectedProposalId) && (
        <div className="fixed inset-0 z-[100] bg-primary-dark/60 backdrop-blur-sm flex items-center justify-center p-4">
           <div className="bg-white dark:bg-bg-cardDark w-full max-w-3xl rounded-[3rem] shadow-2xl flex flex-col max-h-[95vh] overflow-hidden">
              {(() => {
                const p = proposals.find(x => x.id === selectedProposalId)!;
                const isMyProposal = myProposalIds.includes(p.id);
                return (
                  <>
                    <div className="bg-primary text-white p-8">
                       <div className="flex justify-between items-start mb-4">
                         <div className="flex items-center gap-2">
                           <StatusBadge status={p.status} />
                           {isMyProposal && (
                              <span className="bg-white/20 text-white px-2 py-0.5 rounded text-[9px] font-bold uppercase">自分の投稿</span>
                           )}
                         </div>
                         <div className="flex items-center gap-2">
                           {isMyProposal && (
                             <button 
                               onClick={() => handleDeleteProposal(p.id)}
                               className="w-8 h-8 rounded-full hover:bg-red-500 flex items-center justify-center transition-colors"
                             >
                               <span className="material-icons-round text-sm">delete</span>
                             </button>
                           )}
                           <button onClick={() => setSelectedProposalId(null)} className="w-8 h-8 rounded-full hover:bg-white/20 flex items-center justify-center transition-colors">
                             <span className="material-icons-round">close</span>
                           </button>
                         </div>
                       </div>
                       <h2 className="text-3xl font-black">{p.title}</h2>
                    </div>
                    <div className="flex-1 overflow-y-auto p-10 space-y-10">
                       <Stepper currentStatus={p.status} />
                       <div className="flex gap-3 text-sm font-bold text-gray-500 uppercase tracking-widest"><span className="material-icons-round text-sm">folder</span>{p.category}</div>
                       <p className="text-xl leading-relaxed opacity-80 whitespace-pre-wrap">{p.content}</p>
                       {p.adminResponse && (
                         <div className="bg-purple-50 dark:bg-purple-900/10 p-8 rounded-[2rem] border-l-8 border-primary"><h5 className="font-bold text-primary mb-4">生徒会からのコメント</h5><p className="text-lg leading-relaxed">{p.adminResponse}</p></div>
                       )}
                       <div className="pt-8 border-t flex justify-between items-center">
                          <div className="text-3xl font-black text-primary"><span className="text-sm opacity-50">賛同数:</span> {p.signatures.length}</div>
                          <button onClick={() => toggleSignature(p.id)} className={`px-12 py-5 rounded-[1.5rem] font-black shadow-xl transition-all ${user && p.signatures.some(s => s.userId === user.id) ? 'bg-pink-100 text-pink-700' : 'bg-primary text-white hover:scale-105'}`}>{user && p.signatures.some(s => s.userId === user.id) ? '賛同済み' : '賛同する'}</button>
                       </div>
                    </div>
                  </>
                );
              })()}
           </div>
        </div>
      )}

      {/* Admin Edit Modal */}
      {adminEditId && (
        <div className="fixed inset-0 z-[110] bg-black/60 backdrop-blur-md flex items-center justify-center p-4">
           <div className="bg-white dark:bg-bg-cardDark w-full max-w-2xl rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
              <div className="p-8 border-b dark:border-gray-800 flex justify-between items-center">
                <h3 className="text-xl font-black">意見の管理・更新</h3>
                <button onClick={() => setAdminEditId(null)} className="w-10 h-10 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 flex items-center justify-center transition-colors">
                  <span className="material-icons-round">close</span>
                </button>
              </div>
              <div className="p-8 space-y-6">
                <div>
                  <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2">ステータス更新</label>
                  <div className="flex flex-wrap gap-2">
                    {STATUS_STEPS.map(s => (
                      <button 
                        key={s} 
                        onClick={() => setAdminStatusSelect(s)}
                        className={`px-4 py-2 rounded-xl text-xs font-bold border-2 transition-all ${adminStatusSelect === s ? 'border-primary bg-primary/5 text-primary' : 'border-gray-100 dark:border-gray-800 text-gray-400'}`}
                      >
                        {s}
                      </button>
                    ))}
                  </div>
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2">生徒会からの公式回答</label>
                  <textarea 
                    className="w-full min-h-[150px] p-4 bg-gray-50 dark:bg-gray-800 rounded-2xl outline-none focus:ring-2 ring-primary/20 text-sm"
                    placeholder="生徒会としての見解や、今後の予定を記入してください..."
                    value={adminResponseText}
                    onChange={e => setAdminResponseText(e.target.value)}
                  />
                </div>
              </div>
              <div className="p-8 border-t dark:border-gray-800 flex justify-end gap-3">
                <button onClick={() => setAdminEditId(null)} className="px-6 py-3 font-bold text-gray-500">キャンセル</button>
                <button onClick={handleAdminUpdate} className="bg-primary text-white font-black px-8 py-3 rounded-xl shadow-lg hover:scale-105 transition-transform">
                  変更を保存
                </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { analyzeProposal, AIAnalysisResult } from './services/geminiService';

// --- Types ---
interface User {
  id: string;
  name: string;
  email: string;
  role: 'student' | 'teacher' | 'admin';
  class?: string;
}

interface Signature {
  userId: string;
  userName: string;
  timestamp: string;
}

interface Proposal {
  id: number;
  title: string;
  content: string;
  category: string;
  status: '受付中' | '検討中' | '先生と調整中' | '対応済';
  adminResponse: string;
  timestamp: string;
  signatures: Signature[];
}

// --- Constants ---
const STATUS_STEPS = ['受付中', '検討中', '先生と調整中', '対応済'] as const;
const CATEGORIES = ['校則', '設備・環境', '授業', 'その他'];
const ADMIN_EMAIL = '13250076@toda-ed.jp';

// --- Helper Components ---
const StatusBadge: React.FC<{ status: string }> = ({ status }) => {
  const colors: Record<string, string> = {
    '受付中': 'bg-blue-100 text-blue-800 dark:bg-blue-900/40 dark:text-blue-200',
    '検討中': 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/40 dark:text-yellow-200',
    '先生と調整中': 'bg-purple-100 text-purple-800 dark:bg-purple-900/40 dark:text-purple-200',
    '対応済': 'bg-green-100 text-green-800 dark:bg-green-900/40 dark:text-green-200',
  };
  return (
    <span className={`px-2.5 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider ${colors[status] || 'bg-gray-100 text-gray-800'}`}>
      {status}
    </span>
  );
};

const Stepper: React.FC<{ currentStatus: string }> = ({ currentStatus }) => {
  const currentIndex = STATUS_STEPS.indexOf(currentStatus as any);

  return (
    <div className="relative flex justify-between items-center mb-10 px-4">
      <div className="absolute top-1/2 left-0 w-full h-0.5 bg-gray-200 dark:bg-gray-700 -z-0 -translate-y-1/2"></div>
      {STATUS_STEPS.map((step, idx) => {
        const isCompleted = idx < currentIndex;
        const isActive = idx === currentIndex;
        return (
          <div key={step} className="relative z-10 flex flex-col items-center">
            <div 
              className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-sm transition-all duration-300 border-2 ${
                isCompleted || isActive 
                  ? 'bg-primary border-primary text-white shadow-lg shadow-primary/30' 
                  : 'bg-white dark:bg-bg-cardDark border-gray-200 dark:border-gray-700 text-gray-400'
              }`}
            >
              {isCompleted ? <span className="material-icons-round text-lg">check</span> : <span className="text-xs">{idx + 1}</span>}
            </div>
            <span className={`absolute top-12 whitespace-nowrap text-[10px] font-bold transition-colors ${isActive ? 'text-primary dark:text-primary-light' : 'text-gray-400'}`}>
              {step}
            </span>
          </div>
        );
      })}
    </div>
  );
};

// --- Main Component ---
const App: React.FC = () => {
  // --- States ---
  const [user, setUser] = useState<User | null>(null);
  const [view, setView] = useState<'home' | 'proposals' | 'status' | 'login' | 'register' | 'admin'>('home');
  const [proposals, setProposals] = useState<Proposal[]>([]);
  const [myProposalIds, setMyProposalIds] = useState<number[]>([]);
  const [theme, setTheme] = useState<'light' | 'dark'>('light');

  // Modals & Search
  const [isPostModalOpen, setIsPostModalOpen] = useState(false);
  const [selectedProposalId, setSelectedProposalId] = useState<number | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('all');

  // Auth Forms
  const [authForm, setAuthForm] = useState({ name: '', email: '', password: '', confirmPassword: '', role: 'student', class: '' });

  // Proposal Form
  const [postForm, setPostForm] = useState({ title: '', content: '' });
  const [approvedPostForm, setApprovedPostForm] = useState({ title: '', content: '' });
  const [aiResult, setAiResult] = useState<{ loading: boolean; result: AIAnalysisResult | null }>({ loading: false, result: null });
  const [isAIApproved, setIsAIApproved] = useState(false);

  // Admin Controls
  const [adminEditId, setAdminEditId] = useState<number | null>(null);
  const [adminResponseText, setAdminResponseText] = useState('');
  const [adminStatusSelect, setAdminStatusSelect] = useState<Proposal['status']>('受付中');

  // --- Effects ---
  useEffect(() => {
    const saved = localStorage.getItem('schoolProposals');
    if (saved) setProposals(JSON.parse(saved));
    else {
      const seeds: Proposal[] = [
        { id: 1, title: '靴下の色を自由にしたい', content: '現在は黒白紺のみですが、グレーも許可してほしいです。', category: '校則', status: '先生と調整中', adminResponse: '生徒会で検討し、現在は先生方と調整を行っています。', timestamp: new Date().toISOString(), signatures: [] },
        { id: 2, title: '図書室の開館時間延長', content: '放課後もっと勉強したいです。', category: '設備・環境', status: '受付中', adminResponse: '', timestamp: new Date().toISOString(), signatures: [] },
      ];
      setProposals(seeds);
      localStorage.setItem('schoolProposals', JSON.stringify(seeds));
    }

    const savedMyIds = localStorage.getItem('myProposalIds');
    if (savedMyIds) setMyProposalIds(JSON.parse(savedMyIds));

    const savedTheme = localStorage.getItem('theme') as 'light' | 'dark';
    if (savedTheme) setTheme(savedTheme);
  }, []);

  useEffect(() => {
    document.documentElement.classList.toggle('dark', theme === 'dark');
    localStorage.setItem('theme', theme);
  }, [theme]);

  // AI re-validation: Force re-check if text is modified after approval
  useEffect(() => {
    if (isAIApproved && (postForm.title !== approvedPostForm.title || postForm.content !== approvedPostForm.content)) {
      setIsAIApproved(false);
      setAiResult({ loading: false, result: null });
    }
  }, [postForm, isAIApproved, approvedPostForm]);

  // --- Handlers ---
  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (!authForm.email || !authForm.password) return alert("情報を入力してください");

    const isSpecialAdmin = authForm.email === ADMIN_EMAIL;
    setUser({ 
      id: authForm.email, 
      email: authForm.email, 
      name: isSpecialAdmin ? '生徒会管理者' : authForm.email.split('@')[0], 
      role: isSpecialAdmin ? 'admin' : 'student' 
    });
    setView(isSpecialAdmin ? 'admin' : 'home');
  };

  const handleRegister = (e: React.FormEvent) => {
    e.preventDefault();
    if (authForm.password !== authForm.confirmPassword) return alert("パスワードが一致しません");
    setUser({ id: authForm.email, email: authForm.email, name: authForm.name, role: authForm.role as any, class: authForm.class });
    setView('home');
  };

  const handleAIAnalyze = async () => {
    if (!postForm.title || !postForm.content) return alert("タイトルと内容を入力してください");
    setAiResult({ loading: true, result: null });
    const result = await analyzeProposal(postForm.title, postForm.content);
    setAiResult({ loading: false, result });

    if (result.isAppropriate) {
        const finalTitle = result.refinedTitle || postForm.title;
        const finalContent = result.refinedContent || postForm.content;
        setPostForm({ title: finalTitle, content: finalContent });
        setApprovedPostForm({ title: finalTitle, content: finalContent });
        setIsAIApproved(true);
    } else {
        setIsAIApproved(false);
    }
  };

  const handlePostSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!isAIApproved || !aiResult.result) return;
    const newId = Date.now();
    const newProposal: Proposal = {
      id: newId,
      title: postForm.title,
      content: postForm.content,
      category: aiResult.result.category,
      status: '受付中',
      adminResponse: '',
      timestamp: new Date().toISOString(),
      signatures: []
    };
    const updated = [newProposal, ...proposals];
    setProposals(updated);
    localStorage.setItem('schoolProposals', JSON.stringify(updated));

    const updatedMyIds = [...myProposalIds, newId];
    setMyProposalIds(updatedMyIds);
    localStorage.setItem('myProposalIds', JSON.stringify(updatedMyIds));

    setIsPostModalOpen(false);
    setPostForm({ title: '', content: '' });
    setApprovedPostForm({ title: '', content: '' });
    setAiResult({ loading: false, result: null });
    setIsAIApproved(false);
  };

  const handleDeleteProposal = (id: number) => {
    if (!window.confirm("本当にこの意見を削除しますか？")) return;
    const updated = proposals.filter(p => p.id !== id);
    setProposals(updated);
    localStorage.setItem('schoolProposals', JSON.stringify(updated));
    setMyProposalIds(myProposalIds.filter(mid => mid !== id));
    setSelectedProposalId(null);
  };

  const toggleSignature = (id: number) => {
    if (!user) return alert("賛同するにはログインが必要です");
    const updated = proposals.map(p => {
      if (p.id === id) {
        const index = p.signatures.findIndex(s => s.userId === user.id);
        const newSigs = [...p.signatures];
        if (index >= 0) newSigs.splice(index, 1);
        else newSigs.push({ userId: user.id, userName: user.name, timestamp: new Date().toISOString() });
        return { ...p, signatures: newSigs };
      }
      return p;
    });
    setProposals(updated);
    localStorage.setItem('schoolProposals', JSON.stringify(updated));
  };

  const handleAdminUpdate = () => {
    if (!adminEditId) return;
    const updated = proposals.map(p => {
      if (p.id === adminEditId) {
        return { ...p, status: adminStatusSelect, adminResponse: adminResponseText };
      }
      return p;
    });
    setProposals(updated);
    localStorage.setItem('schoolProposals', JSON.stringify(updated));
    setAdminEditId(null);
  };

  // --- Derived ---
  const filteredProposals = useMemo(() => {
    return proposals.filter(p => {
      const matchSearch = p.title.includes(searchTerm) || p.content.includes(searchTerm);
      const matchCat = categoryFilter === 'all' || p.category === categoryFilter;
      return matchSearch && matchCat;
    });
  }, [proposals, searchTerm, categoryFilter]);

  const trendingTags = useMemo(() => {
    const counts: Record<string, number> = {};
    proposals.forEach(p => {
      const tags = p.content.match(/#\w+/g);
      if (tags) tags.forEach(t => counts[t] = (counts[t] || 0) + 1);
    });
    return Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 5);
  }, [proposals]);

  // --- Login / Register Screens ---
  if (!user && (view === 'login' || view === 'register')) {
    return (
      <div className="min-h-screen bg-[#f9f7fa] flex flex-col items-center justify-center p-6 font-sans">
        <div className="mb-10 text-center">
           <div className="flex items-center justify-center gap-2 mb-2">
              <span className="material-icons-round text-[#9d46ff] text-4xl">auto_awesome</span>
              <h1 className="text-4xl font-black text-[#6a0dad]">ProPoSal</h1>
           </div>
           <p className="text-gray-500 font-medium">デジタル校内民主主義プロジェクト</p>
        </div>

        <div className="w-full max-w-md bg-white rounded-[2rem] shadow-xl p-8">
           <div className="flex bg-gray-100 p-1.5 rounded-2xl mb-8">
              <button 
                onClick={() => setView('login')}
                className={`flex-1 py-3 rounded-xl font-bold transition-all ${view === 'login' ? 'bg-white shadow-sm text-black' : 'text-gray-400'}`}
              >ログイン</button>
              <button 
                onClick={() => setView('register')}
