                       </div>
                    </div>
                  </>
                );
              })()}
           </div>
        </div>
      )}

      {/* Admin Edit Modal */}
      {adminEditId && (
        <div className="fixed inset-0 z-[110] bg-black/60 backdrop-blur-md flex items-center justify-center p-4">
           <div className="bg-white dark:bg-bg-cardDark w-full max-w-2xl rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
              <div className="p-8 border-b dark:border-gray-800 flex justify-between items-center bg-gray-50 dark:bg-gray-800/50">
                <h3 className="text-xl font-black">意見の管理・更新</h3>
                <button onClick={() => setAdminEditId(null)} className="w-10 h-10 rounded-full hover:bg-gray-200 dark:hover:bg-gray-700 flex items-center justify-center transition-colors">
                  <span className="material-icons-round">close</span>
                </button>
              </div>
              <div className="p-8 space-y-8">
                <div>
                  <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">ステータス更新</label>
                  <div className="flex flex-wrap gap-2">
                    {STATUS_STEPS.map(s => (
                      <button 
                        key={s} 
                        onClick={() => setAdminStatusSelect(s)}
                        className={`px-4 py-2 rounded-xl text-xs font-bold border-2 transition-all ${adminStatusSelect === s ? 'border-primary bg-primary/5 text-primary' : 'border-gray-100 dark:border-gray-800 text-gray-400 hover:border-gray-300'}`}
                      >
                        {s}
