export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { analyzeProposal, AIAnalysisResult } from './services/geminiService';

// --- Types ---
interface User {
  id: string;
  name: string;
  email: string;
  role: 'student' | 'teacher' | 'admin';
  class?: string;
  password?: string;
  isApproved: boolean; // 生徒会による承認フラグ
}

interface Signature {
  userId: string;
  userName: string;
  timestamp: string;
}

interface Proposal {
  id: number;
  title: string;
  content: string;
  category: string;
  status: '受付中' | '検討中' | '先生と調整中' | '対応済';
  adminResponse: string;
  timestamp: string;
  signatures: Signature[];
}

// --- Constants ---
const STATUS_STEPS = ['受付中', '検討中', '先生と調整中', '対応済'] as const;
const CATEGORIES = ['校則', '設備・環境', '授業', 'その他'];
const ADMIN_EMAIL = '13250076@toda-ed.jp';

// --- Helper Components ---
const StatusBadge: React.FC<{ status: string }> = ({ status }) => {
  const colors: Record<string, string> = {
    '受付中': 'bg-blue-100 text-blue-800 dark:bg-blue-900/40 dark:text-blue-200',
    '検討中': 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/40 dark:text-yellow-200',
    '先生と調整中': 'bg-purple-100 text-purple-800 dark:bg-purple-900/40 dark:text-purple-200',
    '対応済': 'bg-green-100 text-green-800 dark:bg-green-900/40 dark:text-green-200',
  };
  return (
    <span className={`px-2.5 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider ${colors[status] || 'bg-gray-100 text-gray-800'}`}>
      {status}
    </span>
  );
};

const Stepper: React.FC<{ currentStatus: string }> = ({ currentStatus }) => {
  const currentIndex = STATUS_STEPS.indexOf(currentStatus as any);
  return (
    <div className="relative flex justify-between items-center mb-10 px-4">
      <div className="absolute top-1/2 left-0 w-full h-0.5 bg-gray-200 dark:bg-gray-700 -z-0 -translate-y-1/2"></div>
      {STATUS_STEPS.map((step, idx) => {
        const isCompleted = idx < currentIndex;
        const isActive = idx === currentIndex;
        return (
          <div key={step} className="relative z-10 flex flex-col items-center">
            <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-sm transition-all duration-300 border-2 ${isCompleted || isActive ? 'bg-primary border-primary text-white' : 'bg-white dark:bg-bg-cardDark border-gray-200 text-gray-400'}`}>
              {isCompleted ? <span className="material-icons-round text-lg">check</span> : <span className="text-xs">{idx + 1}</span>}
            </div>
            <span className={`absolute top-12 whitespace-nowrap text-[10px] font-bold ${isActive ? 'text-primary' : 'text-gray-400'}`}>{step}</span>
          </div>
        );
      })}
    </div>
  );
};

const App: React.FC = () => {
  // --- States ---
  const [user, setUser] = useState<User | null>(null);
  const [registeredUsers, setRegisteredUsers] = useState<User[]>([]);
  const [view, setView] = useState<'home' | 'proposals' | 'status' | 'login' | 'register' | 'admin' | 'mypage'>('home');
  const [proposals, setProposals] = useState<Proposal[]>([]);
  const [myProposalIds, setMyProposalIds] = useState<number[]>([]);
  const [theme, setTheme] = useState<'light' | 'dark'>('light');
  const [isPostModalOpen, setIsPostModalOpen] = useState(false);
  const [selectedProposalId, setSelectedProposalId] = useState<number | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('all');

  // Auth Forms
  const [authForm, setAuthForm] = useState({ name: '', email: '', password: '', confirmPassword: '', role: 'student', class: '' });
  const [postForm, setPostForm] = useState({ title: '', content: '' });
  const [approvedPostForm, setApprovedPostForm] = useState({ title: '', content: '' });
  const [aiResult, setAiResult] = useState<{ loading: boolean; result: AIAnalysisResult | null }>({ loading: false, result: null });
  const [isAIApproved, setIsAIApproved] = useState(false);

  // Admin Controls
  const [adminTab, setAdminTab] = useState<'proposals' | 'approvals'>('proposals');
  const [adminEditId, setAdminEditId] = useState<number | null>(null);
  const [adminResponseText, setAdminResponseText] = useState('');
  const [adminStatusSelect, setAdminStatusSelect] = useState<Proposal['status']>('受付中');

  // --- Effects ---
  useEffect(() => {
    const savedUsers = localStorage.getItem('proPoSalUsers');
    if (savedUsers) setRegisteredUsers(JSON.parse(savedUsers));

    const savedProposals = localStorage.getItem('schoolProposals');
    if (savedProposals) setProposals(JSON.parse(savedProposals));
    else {
      const seeds: Proposal[] = [
        { id: 1, title: '靴下の色を自由にしたい', content: '現在は黒白紺のみですが、グレーも許可してほしいです。', category: '校則', status: '先生と調整中', adminResponse: '生徒会で検討中。', timestamp: new Date().toISOString(), signatures: [] },
      ];
      setProposals(seeds);
      localStorage.setItem('schoolProposals', JSON.stringify(seeds));
    }
    const savedMyIds = localStorage.getItem('myProposalIds');
    if (savedMyIds) setMyProposalIds(JSON.parse(savedMyIds));
    const savedTheme = localStorage.getItem('theme') as 'light' | 'dark';
    if (savedTheme) setTheme(savedTheme);
    const activeUser = localStorage.getItem('activeUser');
    if (activeUser) setUser(JSON.parse(activeUser));
  }, []);

  useEffect(() => {
    document.documentElement.classList.toggle('dark', theme === 'dark');
    localStorage.setItem('theme', theme);
  }, [theme]);

  // --- Handlers ---
  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (authForm.email === ADMIN_EMAIL && authForm.password === 'admin') {
      const admin: User = { id: ADMIN_EMAIL, email: ADMIN_EMAIL, name: '生徒会管理者', role: 'admin', isApproved: true };
      setUser(admin);
      localStorage.setItem('activeUser', JSON.stringify(admin));
      setView('admin');
      return;
    }
    const found = registeredUsers.find(u => u.email === authForm.email && u.password === authForm.password);
    if (found) {
      setUser(found);
      localStorage.setItem('activeUser', JSON.stringify(found));
      setView('home');
    } else {
      alert("不適切なログイン情報です。");
    }
  };

  const handleRegister = (e: React.FormEvent) => {
    e.preventDefault();
    if (!authForm.name || !authForm.email || !authForm.password) return alert("入力してください");
    if (authForm.password !== authForm.confirmPassword) return alert("不一致");
    if (registeredUsers.some(u => u.email === authForm.email)) return alert("重複");

    const isSpecialAdmin = authForm.email === ADMIN_EMAIL;
    const newUser: User = {
      id: authForm.email,
      email: authForm.email,
      name: authForm.name,
      password: authForm.password,
      role: isSpecialAdmin ? 'admin' : (authForm.role as any),
      class: authForm.class,
      isApproved: isSpecialAdmin
    };
    const updatedUsers = [...registeredUsers, newUser];
    setRegisteredUsers(updatedUsers);
    localStorage.setItem('proPoSalUsers', JSON.stringify(updatedUsers));
    setUser(newUser);
    localStorage.setItem('activeUser', JSON.stringify(newUser));
    setView('home');
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('activeUser');
    setView('home');
  };

  const handleApproveUser = (email: string) => {
    const updated = registeredUsers.map(u => u.email === email ? { ...u, isApproved: true } : u);
    setRegisteredUsers(updated);
    localStorage.setItem('proPoSalUsers', JSON.stringify(updated));
    if (user?.email === email) {
      const u = { ...user, isApproved: true };
      setUser(u);
      localStorage.setItem('activeUser', JSON.stringify(u));
    }
  };

  const handleRejectUser = (email: string) => {
    const updated = registeredUsers.filter(u => u.email !== email);
    setRegisteredUsers(updated);
    localStorage.setItem('proPoSalUsers', JSON.stringify(updated));
  };

  const handlePostSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!isAIApproved || !aiResult.result) return;
    const newProposal: Proposal = {
      id: Date.now(),
      title: postForm.title,
      content: postForm.content,
      category: aiResult.result.category,
      status: '受付中',
      adminResponse: '',
      timestamp: new Date().toISOString(),
      signatures: []
    };
    const updated = [newProposal, ...proposals];
    setProposals(updated);
    localStorage.setItem('schoolProposals', JSON.stringify(updated));
    setIsPostModalOpen(false);
    setPostForm({ title: '', content: '' });
    setIsAIApproved(false);
    setAiResult({ loading: false, result: null });
  };

  const toggleSignature = (id: number) => {
    if (!user) return alert("賛同には実名ログインが必要です");
    if (!user.isApproved) return alert("生徒会による承認がまだ完了していません。マイページでステータスを確認してください。");
    const updated = proposals.map(p => {
      if (p.id === id) {
        const index = p.signatures.findIndex(s => s.userId === user.id);
        const newSigs = [...p.signatures];
        if (index >= 0) newSigs.splice(index, 1);
        else newSigs.push({ userId: user.id, userName: user.name, timestamp: new Date().toISOString() });
        return { ...p, signatures: newSigs };
      }
      return p;
    });
    setProposals(updated);
    localStorage.setItem('schoolProposals', JSON.stringify(updated));
  };

  const handleAdminUpdate = () => {
    const updated = proposals.map(p => p.id === adminEditId ? { ...p, status: adminStatusSelect, adminResponse: adminResponseText } : p);
    setProposals(updated);
    localStorage.setItem('schoolProposals', JSON.stringify(updated));
    setAdminEditId(null);
  };

  const filteredProposals = useMemo(() => {
    return proposals.filter(p => (p.title.includes(searchTerm) || p.content.includes(searchTerm)) && (categoryFilter === 'all' || p.category === categoryFilter));
  }, [proposals, searchTerm, categoryFilter]);

  const pendingUsers = useMemo(() => registeredUsers.filter(u => !u.isApproved), [registeredUsers]);

  // --- Render Sections ---
  if (!user && (view === 'login' || view === 'register')) {
    return (
      <div className="min-h-screen bg-[#f9f7fa] flex flex-col items-center justify-center p-6">
        <div className="mb-10 text-center"><div className="flex items-center justify-center gap-2 mb-2"><span className="material-icons-round text-primary text-4xl">auto_awesome</span><h1 className="text-4xl font-black text-primary-dark">ProPoSal</h1></div></div>
        <div className="w-full max-w-md bg-white rounded-[2rem] shadow-xl p-8">
           <div className="flex bg-gray-100 p-1.5 rounded-2xl mb-8">
              <button onClick={() => setView('login')} className={`flex-1 py-3 rounded-xl font-bold ${view === 'login' ? 'bg-white shadow-sm' : 'text-gray-400'}`}>ログイン</button>
              <button onClick={() => setView('register')} className={`flex-1 py-3 rounded-xl font-bold ${view === 'register' ? 'bg-white shadow-sm' : 'text-gray-400'}`}>新規登録</button>
           </div>
           {view === 'login' ? (
             <form onSubmit={handleLogin} className="space-y-6">
                <input type="email" placeholder="メールアドレス" className="w-full bg-gray-50 rounded-xl p-4 outline-none" value={authForm.email} onChange={e => setAuthForm({...authForm, email: e.target.value})} />
                <input type="password" placeholder="パスワード" className="w-full bg-gray-50 rounded-xl p-4 outline-none" value={authForm.password} onChange={e => setAuthForm({...authForm, password: e.target.value})} />
                <button type="submit" className="w-full bg-primary text-white font-black py-4 rounded-xl shadow-lg">ログイン</button>
             </form>
           ) : (
             <form onSubmit={handleRegister} className="space-y-4">
                <input type="text" placeholder="本名" className="w-full bg-gray-50 rounded-xl p-4 outline-none" value={authForm.name} onChange={e => setAuthForm({...authForm, name: e.target.value})} />
                <input type="email" placeholder="メールアドレス" className="w-full bg-gray-50 rounded-xl p-4 outline-none" value={authForm.email} onChange={e => setAuthForm({...authForm, email: e.target.value})} />
                <input type="password" placeholder="パスワード" className="w-full bg-gray-50 rounded-xl p-4 outline-none" value={authForm.password} onChange={e => setAuthForm({...authForm, password: e.target.value})} />
                <input type="password" placeholder="パスワード確認" className="w-full bg-gray-50 rounded-xl p-4 outline-none" value={authForm.confirmPassword} onChange={e => setAuthForm({...authForm, confirmPassword: e.target.value})} />
                <div className="grid grid-cols-2 gap-3">
                  <select className="bg-gray-50 rounded-xl p-4" value={authForm.role} onChange={e => setAuthForm({...authForm, role: e.target.value as any})}><option value="student">生徒</option><option value="teacher">先生</option></select>
                  <input type="text" placeholder="クラス (1年A組)" className="w-full bg-gray-50 rounded-xl p-4 outline-none" value={authForm.class} onChange={e => setAuthForm({...authForm, class: e.target.value})} />
                </div>
                <button type="submit" className="w-full bg-primary text-white font-black py-4 rounded-xl shadow-lg">アカウント作成</button>
             </form>
           )}
        </div>
        <button onClick={() => setView('home')} className="mt-6 text-gray-500 font-bold">Homeに戻る</button>
      </div>
    );
  }

  return (
    <div className="min-h-screen grid grid-cols-1 md:grid-cols-[240px_1fr] lg:grid-cols-[240px_1fr_300px]">
      {/* Sidebar */}
      <aside className="bg-primary-dark text-white p-6 flex flex-col gap-8 h-screen sticky top-0 z-50 shadow-2xl">
        <div className="flex items-center gap-3"><span className="material-icons-round text-accent text-3xl">school</span><h1 className="text-xl font-black">ProPoSal</h1></div>
        <nav className="flex flex-col gap-1">
          {['home', 'proposals', 'status'].map(v => (
            <button key={v} onClick={() => setView(v as any)} className={`flex items-center gap-4 px-4 py-3 rounded-xl font-bold ${view === v ? 'bg-white/20 border-l-4 border-accent' : 'opacity-70'}`}>
              <span className="material-icons-round">{v === 'home' ? 'home' : v === 'proposals' ? 'campaign' : 'trending_up'}</span>{v === 'home' ? 'Home' : v === 'proposals' ? '意見ボックス' : '進捗状況'}
            </button>
          ))}
          {user && (
            <button onClick={() => setView('mypage')} className={`flex items-center gap-4 px-4 py-3 rounded-xl font-bold ${view === 'mypage' ? 'bg-white/20 border-l-4 border-accent' : 'opacity-70'}`}>
              <span className="material-icons-round">person</span>マイページ
            </button>
          )}
          {user?.role === 'admin' && (
            <button onClick={() => setView('admin')} className={`flex items-center gap-4 px-4 py-3 rounded-xl font-bold ${view === 'admin' ? 'bg-white/20 border-l-4 border-accent' : 'opacity-70'}`}>
              <span className="material-icons-round">admin_panel_settings</span>生徒会管理
            </button>
          )}
        </nav>
        <button onClick={() => setIsPostModalOpen(true)} className="bg-accent text-primary-dark font-black py-4 rounded-2xl shadow-xl mt-4">意見を投稿する</button>
        <div className="mt-auto pt-6 border-t border-white/10">
          {user ? (
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-white text-primary-dark rounded-full flex items-center justify-center font-bold">{user.name.charAt(0)}</div>
              <div className="flex-1 min-w-0"><div className="font-bold text-sm truncate">{user.name}</div><div className="text-[10px] opacity-50 uppercase">{user.role}</div></div>
              <button onClick={handleLogout}><span className="material-icons-round text-lg">logout</span></button>
            </div>
          ) : (
            <button onClick={() => setView('login')} className="w-full bg-white/10 py-3 rounded-xl border border-white/20">ログイン</button>
          )}
        </div>
      </aside>

      {/* Main Content */}
      <main className="bg-bg-body dark:bg-bg-dark overflow-y-auto">
        <header className="px-8 py-6 flex justify-between items-center sticky top-0 bg-bg-body/80 backdrop-blur-md z-40">
           <h2 className="text-2xl font-black">{view === 'home' ? 'Home' : view === 'proposals' ? '意見ボックス' : view === 'status' ? '進捗状況' : view === 'admin' ? '生徒会管理' : 'マイページ'}</h2>
           <button onClick={() => setTheme(t => t === 'light' ? 'dark' : 'light')} className="w-10 h-10 rounded-full bg-white shadow-sm flex items-center justify-center"><span className="material-icons-round">{theme === 'light' ? 'dark_mode' : 'light_mode'}</span></button>
        </header>

        <div className="px-8 pb-12">
          {view === 'home' && (
            <div className="space-y-10">
               <div className="p-12 rounded-[2rem] bg-gradient-to-br from-primary to-primary-light text-white shadow-2xl text-center">
                  <h3 className="text-5xl font-black mb-6">テクノロジーで、<br/>学校は変えられる。</h3>
                  <p className="opacity-90 text-xl max-w-2xl mx-auto">匿名で声を上げ、実名で賛同する。誰もが参加できる民主的な学校へ。</p>
               </div>
               <div className="space-y-6">
                 {filteredProposals.map(p => (
                   <div key={p.id} onClick={() => setSelectedProposalId(p.id)} className="bg-white p-8 rounded-[2rem] shadow-sm hover:shadow-xl cursor-pointer border-l-8 border-primary transition-all">
                     <div className="flex justify-between items-center mb-4"><StatusBadge status={p.status} /><div className="flex items-center gap-1 text-pink-500 font-black"><span className="material-icons-round text-sm">thumb_up</span>{p.signatures.length}</div></div>
                     <h4 className="text-2xl font-black mb-3">{p.title}</h4>
                     <p className="opacity-60 line-clamp-2">{p.content}</p>
                   </div>
                 ))}
               </div>
            </div>
          )}

          {view === 'proposals' && (
             <div className="space-y-6">
                {filteredProposals.map(p => (
                  <div key={p.id} onClick={() => setSelectedProposalId(p.id)} className="bg-white p-8 rounded-[2rem] shadow-sm hover:shadow-xl cursor-pointer transition-all">
                     <div className="flex justify-between mb-4"><StatusBadge status={p.status} /><span className="text-xs opacity-40 font-bold uppercase">{p.category}</span></div>
                     <h4 className="text-xl font-bold mb-2">{p.title}</h4>
                     <p className="opacity-60 line-clamp-3 mb-4">{p.content}</p>
                     <div className="flex justify-between items-center text-xs opacity-40 font-bold"><div>{new Date(p.timestamp).toLocaleDateString()}</div><div>賛同 {p.signatures.length}人</div></div>
                  </div>
                ))}
             </div>
          )}

          {view === 'admin' && (
            <div className="space-y-8">
               <div className="bg-gray-100 p-1 rounded-2xl flex gap-2 w-fit">
                 <button onClick={() => setAdminTab('proposals')} className={`px-6 py-2 rounded-xl font-bold ${adminTab === 'proposals' ? 'bg-white shadow' : 'text-gray-400'}`}>意見管理</button>
                 <button onClick={() => setAdminTab('approvals')} className={`px-6 py-2 rounded-xl font-bold ${adminTab === 'approvals' ? 'bg-white shadow' : 'text-gray-400'}`}>アカウント承認 <span className="bg-red-500 text-white text-[10px] px-1.5 rounded-full">{pendingUsers.length}</span></button>
               </div>
               {adminTab === 'proposals' ? (
                 <div className="bg-white p-6 rounded-3xl shadow-sm overflow-hidden">
                    <table className="w-full text-left">
                      <thead className="text-xs text-gray-400 border-b"><tr><th className="pb-4">日時</th><th className="pb-4">タイトル</th><th className="pb-4 text-right">アクション</th></tr></thead>
                      <tbody>
                        {proposals.map(p => (
                          <tr key={p.id} className="border-b last:border-none">
                            <td className="py-4 text-xs opacity-50">{new Date(p.timestamp).toLocaleDateString()}</td>
                            <td className="py-4 font-bold">{p.title}</td>
                            <td className="py-4 text-right"><button onClick={() => {setAdminEditId(p.id); setAdminResponseText(p.adminResponse);}} className="text-primary font-bold text-xs">編集</button></td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                 </div>
               ) : (
                 <div className="space-y-4">
                   {pendingUsers.map(u => (
                     <div key={u.email} className="bg-white p-6 rounded-3xl shadow-sm flex items-center justify-between">
                        <div><div className="font-bold">{u.name} <span className="text-xs text-gray-400">({u.class})</span></div><div className="text-xs opacity-50">{u.email}</div></div>
                        <div className="flex gap-2">
                           <button onClick={() => handleRejectUser(u.email)} className="bg-red-50 text-red-600 px-4 py-2 rounded-xl text-xs font-bold">拒否</button>
                           <button onClick={() => handleApproveUser(u.email)} className="bg-black text-white px-4 py-2 rounded-xl text-xs font-bold">承認する</button>
                        </div>
                     </div>
                   ))}
                   {pendingUsers.length === 0 && <div className="text-center py-20 opacity-30">承認待ちのアカウントはありません</div>}
                 </div>
               )}
            </div>
          )}

          {view === 'mypage' && user && (
            <div className="max-w-3xl mx-auto space-y-8">
               <div className="bg-white p-10 rounded-[3rem] shadow-sm border">
                  <h3 className="text-2xl font-black mb-8 flex items-center gap-3">アカウント情報</h3>
                  <div className="flex items-center gap-8 mb-10">
                     <div className="w-24 h-24 bg-gray-100 rounded-full flex items-center justify-center text-4xl font-black text-gray-300">{user.name.charAt(0)}</div>
                     <div>
                        <div className="flex items-center gap-3 mb-1"><h4 className="text-3xl font-black">{user.name}</h4><span className="bg-black text-white px-3 py-1 rounded-full text-[10px] font-black uppercase">{user.role}</span></div>
                        <p className="text-lg opacity-40 font-bold">{user.class || 'クラス未設定'}</p>
                     </div>
                  </div>
                  <div className="grid grid-cols-2 gap-8 pt-8 border-t mb-10">
                     <div><div className="text-[10px] text-gray-400 font-bold uppercase mb-1">メールアドレス</div><div className="font-bold">{user.email}</div></div>
                     <div><div className="text-[10px] text-gray-400 font-bold uppercase mb-1">所属クラス</div><div className="font-bold">{user.class || '未設定'}</div></div>
                  </div>
                  <div className={`p-6 rounded-[2rem] flex items-center gap-4 ${user.isApproved ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-yellow-50 text-yellow-700 border border-yellow-200'}`}>
                     <span className="material-icons-round text-3xl">{user.isApproved ? 'verified_user' : 'hourglass_empty'}</span>
                     <div>
                        <div className="font-black">{user.isApproved ? '承認済みのアカウントです' : '承認待ちのアカウントです'}</div>
                        <p className="text-xs opacity-70">{user.isApproved ? 'すべての機能をご利用いただけます。' : '生徒会による本人確認中です。完了するまで賛同機能は制限されます。'}</p>
                     </div>
                  </div>
               </div>
               <div className="bg-white p-10 rounded-[3rem] shadow-sm border border-red-100">
                  <h4 className="text-xl font-black text-red-500 mb-4">危険な操作</h4>
                  <button onClick={() => { if(window.confirm("本当に削除しますか？")) handleRejectUser(user.email); }} className="bg-red-500 text-white font-black px-8 py-4 rounded-2xl shadow-lg">アカウントを削除</button>
               </div>
            </div>
          )}
        </div>
      </main>

      {/* Right Sidebar */}
      <aside className="bg-bg-body dark:bg-bg-dark border-l p-8 space-y-10 hidden lg:block">
         <div className="bg-white p-6 rounded-3xl shadow-sm border">
            <div className="font-bold text-primary mb-4 flex items-center gap-2 text-sm"><span className="material-icons-round text-sm">search</span>検索</div>
            <input type="text" placeholder="キーワード検索..." className="w-full bg-gray-50 p-4 rounded-2xl text-xs outline-none" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
         </div>
         <div>
            <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4">カテゴリー</h4>
            <div className="flex flex-wrap gap-2">
              {['all', ...CATEGORIES].map(c => (
                <button key={c} onClick={() => setCategoryFilter(c)} className={`px-4 py-2 rounded-xl text-[10px] font-black border transition-all ${categoryFilter === c ? 'bg-primary text-white' : 'bg-white'}`}>{c === 'all' ? '全て' : c}</button>
              ))}
            </div>
         </div>
      </aside>

      {/* Post Modal */}
      {isPostModalOpen && (
        <div className="fixed inset-0 z-[100] bg-black/40 backdrop-blur-md flex items-center justify-center p-4">
           <div className="bg-white w-full max-w-2xl rounded-[3rem] shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
              <div className="p-8 bg-primary text-white flex justify-between items-center"><h2 className="text-2xl font-black">意見を投稿する</h2><button onClick={() => setIsPostModalOpen(false)}><span className="material-icons-round">close</span></button></div>
              <div className="p-8 flex-1 overflow-y-auto space-y-6">
                 <input type="text" placeholder="タイトル" className="w-full text-2xl font-black border-b pb-4 outline-none" value={postForm.title} onChange={e => setPostForm({...postForm, title: e.target.value})} />
                 <textarea placeholder="内容を詳しく入力してください..." className="w-full min-h-[200px] p-6 bg-gray-50 rounded-3xl outline-none" value={postForm.content} onChange={e => setPostForm({...postForm, content: e.target.value})} />
                 <div className={`p-6 rounded-3xl border ${isAIApproved ? 'bg-green-50 border-green-200' : 'bg-primary/5'}`}>
                    <div className="flex justify-between items-center mb-2"><h5 className="font-bold">AIアドバイザー</h5>{!isAIApproved && <button onClick={async () => {
                      setAiResult({ loading: true, result: null });
                      const res = await analyzeProposal(postForm.title, postForm.content);
                      setAiResult({ loading: false, result: res });
                      if(res.isAppropriate) setIsAIApproved(true);
                    }} className="bg-primary text-white px-4 py-1.5 rounded-full text-xs font-bold shadow">{aiResult.loading ? '中...' : 'チェック'}</button>}</div>
                    {aiResult.result && <p className="text-xs opacity-70">{aiResult.result.advice}</p>}
                 </div>
              </div>
              {isAIApproved && <div className="p-8 border-t flex justify-end"><button onClick={handlePostSubmit} className="bg-primary text-white font-black px-12 py-4 rounded-2xl shadow-xl">送信する</button></div>}
           </div>
        </div>
      )}

      {/* Selected Proposal Modal */}
      {selectedProposalId && (
         <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-white w-full max-w-3xl rounded-[3rem] shadow-2xl overflow-hidden">
               {(() => {
                 const p = proposals.find(x => x.id === selectedProposalId);
                 if (!p) return null;
                 return (
                   <>
                     <div className="p-10 bg-primary text-white flex justify-between items-start">
                        <div><StatusBadge status={p.status} /><h3 className="text-3xl font-black mt-4">{p.title}</h3></div>
                        <button onClick={() => setSelectedProposalId(null)}><span className="material-icons-round">close</span></button>
                     </div>
                     <div className="p-10 space-y-10 max-h-[70vh] overflow-y-auto">
                        <Stepper currentStatus={p.status} />
                        <p className="text-lg opacity-80 whitespace-pre-wrap">{p.content}</p>
                        {p.adminResponse && <div className="bg-purple-50 p-8 rounded-[2rem] border-l-8 border-primary"><h5 className="font-black text-primary mb-2">生徒会からの回答</h5><p>{p.adminResponse}</p></div>}
                        <div className="pt-8 border-t flex justify-between items-center">
                           <div className="text-3xl font-black text-primary"><span className="text-xs opacity-40 mr-2">賛同数</span>{p.signatures.length}</div>
                           <button onClick={() => toggleSignature(p.id)} className={`px-12 py-5 rounded-[1.5rem] font-black transition-all ${user && p.signatures.find(s => s.userId === user.id) ? 'bg-pink-100 text-pink-600' : 'bg-primary text-white shadow-xl'}`}>
                             {user && p.signatures.find(s => s.userId === user.id) ? '賛同済み' : '賛同する'}
                           </button>
                        </div>
                     </div>
                   </>
                 );
               })()}
            </div>
         </div>
      )}

      {/* Admin Edit Modal */}
      {adminEditId && (
        <div className="fixed inset-0 z-[110] bg-black/60 backdrop-blur-md flex items-center justify-center p-4">
           <div className="bg-white w-full max-w-xl rounded-[2.5rem] p-8 space-y-8">
              <h3 className="text-xl font-black">意見の更新</h3>
              <div><label className="block text-xs font-black opacity-40 mb-2 uppercase">ステータス</label>
                <div className="flex flex-wrap gap-2">{STATUS_STEPS.map(s => <button key={s} onClick={() => setAdminStatusSelect(s)} className={`px-4 py-2 rounded-xl text-xs font-bold border ${adminStatusSelect === s ? 'bg-primary text-white' : 'bg-gray-50'}`}>{s}</button>)}</div>
              </div>
              <div><label className="block text-xs font-black opacity-40 mb-2 uppercase">公式回答</label><textarea className="w-full bg-gray-50 p-4 rounded-xl h-32 outline-none" value={adminResponseText} onChange={e => setAdminResponseText(e.target.value)} /></div>
              <div className="flex justify-end gap-3"><button onClick={() => setAdminEditId(null)} className="font-bold opacity-40">キャンセル</button><button onClick={handleAdminUpdate} className="bg-primary text-white font-black px-8 py-3 rounded-xl shadow-lg">保存</button></div>
           </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { analyzeProposal, AIAnalysisResult } from './services/geminiService';

// --- Types ---
interface User {
  id: string;
  name: string;
  email: string;
  role: 'student' | 'teacher' | 'admin';
  class?: string;
  password?: string;
  isApproved: boolean; // 生徒会による承認状態
}

interface Signature {
  userId: string;
  userName: string;
  timestamp: string;
}

interface Proposal {
  id: number;
  title: string;
  content: string;
  category: string;
  status: '受付中' | '検討中' | '先生と調整中' | '対応済';
  adminResponse: string;
  timestamp: string;
  signatures: Signature[];
}

// --- Constants ---
const STATUS_STEPS = ['受付中', '検討中', '先生と調整中', '対応済'] as const;
const CATEGORIES = ['校則', '設備・環境', '授業', 'その他'];
const ADMIN_EMAIL = '13250076@toda-ed.jp';

// --- Helper Components ---
const StatusBadge: React.FC<{ status: string }> = ({ status }) => {
  const colors: Record<string, string> = {
    '受付中': 'bg-blue-100 text-blue-800 dark:bg-blue-900/40 dark:text-blue-200',
    '検討中': 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/40 dark:text-yellow-200',
    '先生と調整中': 'bg-purple-100 text-purple-800 dark:bg-purple-900/40 dark:text-purple-200',
    '対応済': 'bg-green-100 text-green-800 dark:bg-green-900/40 dark:text-green-200',
  };
  return (
    <span className={`px-2.5 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider ${colors[status] || 'bg-gray-100 text-gray-800'}`}>
      {status}
    </span>
  );
};

const Stepper: React.FC<{ currentStatus: string }> = ({ currentStatus }) => {
  const currentIndex = STATUS_STEPS.indexOf(currentStatus as any);
  return (
    <div className="relative flex justify-between items-center mb-10 px-4">
      <div className="absolute top-1/2 left-0 w-full h-0.5 bg-gray-200 dark:bg-gray-700 -z-0 -translate-y-1/2"></div>
      {STATUS_STEPS.map((step, idx) => {
        const isCompleted = idx < currentIndex;
        const isActive = idx === currentIndex;
        return (
          <div key={step} className="relative z-10 flex flex-col items-center">
            <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-sm border-2 ${isCompleted || isActive ? 'bg-primary border-primary text-white shadow-lg shadow-primary/30' : 'bg-white dark:bg-bg-cardDark border-gray-200 text-gray-400'}`}>
              {isCompleted ? <span className="material-icons-round text-lg">check</span> : <span className="text-xs">{idx + 1}</span>}
            </div>
            <span className={`absolute top-12 whitespace-nowrap text-[10px] font-bold ${isActive ? 'text-primary' : 'text-gray-400'}`}>{step}</span>
          </div>
        );
      })}
    </div>
  );
};

const App: React.FC = () => {
  // --- States ---
  const [user, setUser] = useState<User | null>(null);
  const [registeredUsers, setRegisteredUsers] = useState<User[]>([]);
  const [view, setView] = useState<'home' | 'proposals' | 'status' | 'login' | 'register' | 'admin' | 'mypage'>('home');
  const [proposals, setProposals] = useState<Proposal[]>([]);
  const [myProposalIds, setMyProposalIds] = useState<number[]>([]);
  const [theme, setTheme] = useState<'light' | 'dark'>('light');

  // UI states
  const [isPostModalOpen, setIsPostModalOpen] = useState(false);
  const [selectedProposalId, setSelectedProposalId] = useState<number | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('all');

  // Auth & Admin Tab
  const [authForm, setAuthForm] = useState({ name: '', email: '', password: '', confirmPassword: '', role: 'student', class: '' });
  const [adminTab, setAdminTab] = useState<'dashboard' | 'approvals'>('dashboard');

  // Proposal Form
  const [postForm, setPostForm] = useState({ title: '', content: '' });
  const [approvedPostForm, setApprovedPostForm] = useState({ title: '', content: '' });
  const [aiResult, setAiResult] = useState<{ loading: boolean; result: AIAnalysisResult | null }>({ loading: false, result: null });
  const [isAIApproved, setIsAIApproved] = useState(false);

  // Admin edit
  const [adminEditId, setAdminEditId] = useState<number | null>(null);
  const [adminResponseText, setAdminResponseText] = useState('');
  const [adminStatusSelect, setAdminStatusSelect] = useState<Proposal['status']>('受付中');

  // --- Initial Data Load ---
  useEffect(() => {
    const savedUsers = localStorage.getItem('proPoSalUsers');
    if (savedUsers) setRegisteredUsers(JSON.parse(savedUsers));

    const savedProposals = localStorage.getItem('schoolProposals');
    if (savedProposals) setProposals(JSON.parse(savedProposals));
    else {
      const seeds: Proposal[] = [
        { id: 1, title: '靴下の色を自由にしたい', content: '現在は黒白紺のみですが、グレーも許可してほしいです。', category: '校則', status: '先生と調整中', adminResponse: '現在検討中です。', timestamp: new Date().toISOString(), signatures: [] },
      ];
      setProposals(seeds);
      localStorage.setItem('schoolProposals', JSON.stringify(seeds));
    }

    const savedMyIds = localStorage.getItem('myProposalIds');
    if (savedMyIds) setMyProposalIds(JSON.parse(savedMyIds));
    const savedTheme = localStorage.getItem('theme') as 'light' | 'dark';
    if (savedTheme) setTheme(savedTheme || 'light');
    const activeUser = localStorage.getItem('activeUser');
    if (activeUser) setUser(JSON.parse(activeUser));
  }, []);

  useEffect(() => {
    document.documentElement.classList.toggle('dark', theme === 'dark');
    localStorage.setItem('theme', theme);
  }, [theme]);

  // --- Auth Handlers ---
  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (authForm.email === ADMIN_EMAIL && authForm.password === 'admin') {
      const admin: User = { id: ADMIN_EMAIL, email: ADMIN_EMAIL, name: '生徒会管理者', role: 'admin', isApproved: true };
      setUser(admin);
      localStorage.setItem('activeUser', JSON.stringify(admin));
      setView('admin');
      return;
    }
    const found = registeredUsers.find(u => u.email === authForm.email && u.password === authForm.password);
    if (found) {
      setUser(found);
      localStorage.setItem('activeUser', JSON.stringify(found));
      setView('home');
    } else {
      alert("ログイン情報が正しくありません。");
    }
  };

  const handleRegister = (e: React.FormEvent) => {
    e.preventDefault();
    if (!authForm.name || !authForm.email || !authForm.password) return alert("必須項目を入力してください");
    if (authForm.password !== authForm.confirmPassword) return alert("パスワードが一致しません");
    if (registeredUsers.some(u => u.email === authForm.email)) return alert("このメールは既に登録されています");

    const isSpecialAdmin = authForm.email === ADMIN_EMAIL;
    const newUser: User = {
      id: authForm.email,
      email: authForm.email,
      name: authForm.name,
      password: authForm.password,
      role: isSpecialAdmin ? 'admin' : (authForm.role as any),
      class: authForm.class,
      isApproved: isSpecialAdmin // 管理者は即時承認
    };
    const updatedUsers = [...registeredUsers, newUser];
    setRegisteredUsers(updatedUsers);
    localStorage.setItem('proPoSalUsers', JSON.stringify(updatedUsers));
    setUser(newUser);
    localStorage.setItem('activeUser', JSON.stringify(newUser));
    setView('home');
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('activeUser');
    setView('home');
  };

  const handleDeleteAccount = () => {
    if (!user) return;
    if (!window.confirm("本当にアカウントを削除しますか？")) return;
    const updated = registeredUsers.filter(u => u.email !== user.email);
    setRegisteredUsers(updated);
    localStorage.setItem('proPoSalUsers', JSON.stringify(updated));
    handleLogout();
  };

  // --- Approval Handlers ---
  const handleApproveUser = (email: string) => {
    const updated = registeredUsers.map(u => u.email === email ? { ...u, isApproved: true } : u);
    setRegisteredUsers(updated);
    localStorage.setItem('proPoSalUsers', JSON.stringify(updated));
    if (user?.email === email) {
      const u = { ...user, isApproved: true };
      setUser(u);
      localStorage.setItem('activeUser', JSON.stringify(u));
    }
  };

  const handleRejectUser = (email: string) => {
    const updated = registeredUsers.filter(u => u.email !== email);
    setRegisteredUsers(updated);
    localStorage.setItem('proPoSalUsers', JSON.stringify(updated));
  };

  // --- Proposal Handlers ---
  const handleAIAnalyze = async () => {
    if (!postForm.title || !postForm.content) return alert("入力してください");
    setAiResult({ loading: true, result: null });
    const res = await analyzeProposal(postForm.title, postForm.content);
    setAiResult({ loading: false, result: res });
    if (res.isAppropriate) {
      setPostForm({ title: res.refinedTitle || postForm.title, content: res.refinedContent || postForm.content });
      setApprovedPostForm({ title: res.refinedTitle || postForm.title, content: res.refinedContent || postForm.content });
      setIsAIApproved(true);
    }
  };

  const handlePostSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!isAIApproved || !aiResult.result) return;
    const newId = Date.now();
    const newProposal: Proposal = {
      id: newId,
      title: postForm.title,
      content: postForm.content,
      category: aiResult.result.category,
      status: '受付中',
      adminResponse: '',
      timestamp: new Date().toISOString(),
      signatures: []
    };
    const updated = [newProposal, ...proposals];
    setProposals(updated);
    localStorage.setItem('schoolProposals', JSON.stringify(updated));
    setIsPostModalOpen(false);
    setPostForm({ title: '', content: '' });
    setIsAIApproved(false);
    setAiResult({ loading: false, result: null });
  };

  const toggleSignature = (id: number) => {
    if (!user) return alert("賛同するには実名ログインが必要です");
    if (!user.isApproved) return alert("アカウントが未承認です。生徒会の承認をお待ちください。");
    const updated = proposals.map(p => {
      if (p.id === id) {
        const index = p.signatures.findIndex(s => s.userId === user.id);
        const newSigs = [...p.signatures];
        if (index >= 0) newSigs.splice(index, 1);
        else newSigs.push({ userId: user.id, userName: user.name, timestamp: new Date().toISOString() });
        return { ...p, signatures: newSigs };
      }
      return p;
    });
    setProposals(updated);
    localStorage.setItem('schoolProposals', JSON.stringify(updated));
  };

  const handleAdminUpdate = () => {
    const updated = proposals.map(p => p.id === adminEditId ? { ...p, status: adminStatusSelect, adminResponse: adminResponseText } : p);
    setProposals(updated);
    localStorage.setItem('schoolProposals', JSON.stringify(updated));
    setAdminEditId(null);
  };

  // --- Derived ---
  const filteredProposals = useMemo(() => {
    return proposals.filter(p => (p.title.includes(searchTerm) || p.content.includes(searchTerm)) && (categoryFilter === 'all' || p.category === categoryFilter));
  }, [proposals, searchTerm, categoryFilter]);

  const pendingUsers = useMemo(() => registeredUsers.filter(u => !u.isApproved), [registeredUsers]);

  // --- Render Sections ---
  if (!user && (view === 'login' || view === 'register')) {
    return (
      <div className="min-h-screen bg-bg-body flex flex-col items-center justify-center p-6">
        <div className="mb-10 text-center"><div className="flex items-center justify-center gap-2 mb-2"><span className="material-icons-round text-primary text-4xl">auto_awesome</span><h1 className="text-4xl font-black text-primary-dark">ProPoSal</h1></div><p className="text-gray-500 font-medium">デジタル校内民主主義</p></div>
        <div className="w-full max-w-md bg-white rounded-[2rem] shadow-xl p-8">
           <div className="flex bg-gray-100 p-1.5 rounded-2xl mb-8">
              <button onClick={() => setView('login')} className={`flex-1 py-3 rounded-xl font-bold transition-all ${view === 'login' ? 'bg-white shadow-sm' : 'text-gray-400'}`}>ログイン</button>
              <button onClick={() => setView('register')} className={`flex-1 py-3 rounded-xl font-bold transition-all ${view === 'register' ? 'bg-white shadow-sm' : 'text-gray-400'}`}>新規登録</button>
           </div>
           {view === 'login' ? (
             <form onSubmit={handleLogin} className="space-y-6">
                <input type="email" placeholder="メールアドレス" className="w-full bg-gray-50 rounded-xl p-4 outline-none" value={authForm.email} onChange={e => setAuthForm({...authForm, email: e.target.value})} />
                <input type="password" placeholder="パスワード" className="w-full bg-gray-50 rounded-xl p-4 outline-none" value={authForm.password} onChange={e => setAuthForm({...authForm, password: e.target.value})} />
                <button type="submit" className="w-full bg-black text-white font-black py-4 rounded-xl shadow-lg">Log in</button>
             </form>
           ) : (
             <form onSubmit={handleRegister} className="space-y-4">
                <input type="text" placeholder="本名" className="w-full bg-gray-50 rounded-xl p-4 outline-none" value={authForm.name} onChange={e => setAuthForm({...authForm, name: e.target.value})} />
                <input type="email" placeholder="メールアドレス" className="w-full bg-gray-50 rounded-xl p-4 outline-none" value={authForm.email} onChange={e => setAuthForm({...authForm, email: e.target.value})} />
                <input type="password" placeholder="パスワード" className="w-full bg-gray-50 rounded-xl p-4 outline-none" value={authForm.password} onChange={e => setAuthForm({...authForm, password: e.target.value})} />
                <input type="password" placeholder="パスワード確認" className="w-full bg-gray-50 rounded-xl p-4 outline-none" value={authForm.confirmPassword} onChange={e => setAuthForm({...authForm, confirmPassword: e.target.value})} />
                <div className="grid grid-cols-2 gap-3">
                  <select className="bg-gray-50 rounded-xl p-4 font-bold" value={authForm.role} onChange={e => setAuthForm({...authForm, role: e.target.value as any})}><option value="student">生徒</option><option value="teacher">先生</option></select>
                  <input type="text" placeholder="1年3組" className="w-full bg-gray-50 rounded-xl p-4 outline-none" value={authForm.class} onChange={e => setAuthForm({...authForm, class: e.target.value})} />
                </div>
                <button type="submit" className="w-full bg-black text-white font-black py-4 rounded-xl shadow-lg mt-4">アカウント作成</button>
             </form>
           )}
        </div>
        <button onClick={() => setView('home')} className="mt-8 flex items-center gap-2 text-gray-500 font-bold"><span className="material-icons-round">home</span> Homeに戻る</button>
      </div>
    );
  }

