              <span className="material-icons-round">{v === 'home' ? 'home' : v === 'proposals' ? 'campaign' : 'trending_up'}</span>{v === 'home' ? 'Home' : v === 'proposals' ? '意見ボックス' : '進捗・ステータス'}
            </button>
