                  <div className={`p-8 rounded-[2rem] flex items-center gap-6 border-2 ${user.isApproved ? 'bg-green-50 border-green-100 text-green-700' : 'bg-yellow-50 border-yellow-100 text-yellow-700'}`}>
                     <span className="material-icons-round text-4xl">{user.isApproved ? 'verified_user' : 'pending_actions'}</span>
                     <div>
                        <div className="text-xl font-black">{user.isApproved ? '承認済みのアカウントです' : '承認待ちのアカウントです'}</div>
                        <p className="opacity-80 text-sm leading-relaxed">{user.isApproved ? 'すべての機能（実名賛同を含む）をご利用いただけます。' : '生徒会による本人確認を行っています。承認されるまで「賛同機能」は制限されます。'}</p>
                     </div>
                  </div>
               </div>
               <div className="bg-white p-12 rounded-[3rem] shadow-sm border border-red-100">
                  <h4 className="text-2xl font-black text-red-500 mb-2 flex items-center gap-2"><span className="material-icons-round">warning</span> 危険な操作</h4>
                  <p className="text-sm opacity-50 mb-8 font-bold">アカウントを完全に削除します。この操作は元に戻せません。</p>
                  <button onClick={handleDeleteAccount} className="bg-red-500 text-white font-black px-10 py-5 rounded-2xl shadow-xl hover:scale-105 transition-transform flex items-center gap-2"><span className="material-icons-round">person_remove</span> アカウントを削除</button>
               </div>
            </div>
          )}

          {view === 'admin' && user?.role === 'admin' && (
            <div className="space-y-8 animate-in fade-in duration-500">
               <div className="grid grid-cols-3 gap-6">
                  <div className="bg-white p-8 rounded-[2rem] shadow-sm flex items-center justify-between">
                    <div><div className="text-[10px] font-black text-gray-400 uppercase mb-1">承認待ち</div><div className="text-4xl font-black">{pendingUsers.length}</div></div>
                    <span className="material-icons-round text-4xl opacity-10">person_add</span>
                  </div>
                  <div className="bg-white p-8 rounded-[2rem] shadow-sm flex items-center justify-between">
                    <div><div className="text-[10px] font-black text-gray-400 uppercase mb-1">総ユーザー数</div><div className="text-4xl font-black">{registeredUsers.length}</div></div>
                    <span className="material-icons-round text-4xl opacity-10">group</span>
                  </div>
                  <div className="bg-white p-8 rounded-[2rem] shadow-sm flex items-center justify-between">
                    <div><div className="text-[10px] font-black text-gray-400 uppercase mb-1">投稿意見数</div><div className="text-4xl font-black">{proposals.length}</div></div>
                    <span className="material-icons-round text-4xl opacity-10">campaign</span>
                  </div>
               </div>

               <div className="bg-gray-100 p-1.5 rounded-2xl flex gap-2 w-fit">
                  <button onClick={() => setAdminTab('dashboard')} className={`px-8 py-3 rounded-xl font-black text-sm transition-all ${adminTab === 'dashboard' ? 'bg-white shadow' : 'text-gray-400'}`}>意見管理</button>
                  <button onClick={() => setAdminTab('approvals')} className={`px-8 py-3 rounded-xl font-black text-sm transition-all flex items-center gap-2 ${adminTab === 'approvals' ? 'bg-white shadow' : 'text-gray-400'}`}>アカウント承認 <span className="bg-red-500 text-white text-[10px] px-2 py-0.5 rounded-full font-black">{pendingUsers.length}</span></button>
               </div>

               {adminTab === 'dashboard' ? (
                 <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-gray-50 overflow-hidden">
                    <table className="w-full text-left">
                       <thead className="text-[10px] font-black text-gray-400 uppercase border-b"><tr><th className="pb-6">タイトル</th><th className="pb-6">状態</th><th className="pb-6">賛同</th><th className="pb-6 text-right">操作</th></tr></thead>
                       <tbody className="divide-y">
                         {proposals.map(p => (
                            <tr key={p.id} className="hover:bg-gray-50 transition-colors">
                               <td className="py-6 font-bold">{p.title}</td>
                               <td className="py-6"><StatusBadge status={p.status} /></td>
                               <td className="py-6 font-black text-pink-500">{p.signatures.length}</td>
                               <td className="py-6 text-right"><button onClick={() => {setAdminEditId(p.id); setAdminResponseText(p.adminResponse); setAdminStatusSelect(p.status);}} className="text-primary font-black text-xs hover:underline">編集</button></td>
                            </tr>
                         ))}
                       </tbody>
                    </table>
                 </div>
               ) : (
                 <div className="space-y-4">
                    {pendingUsers.map(u => (
                      <div key={u.email} className="bg-white p-8 rounded-[2.5rem] shadow-sm flex items-center justify-between animate-in slide-in-from-left duration-300">
                         <div className="flex items-center gap-6">
                            <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center font-black text-2xl text-gray-300">{u.name.charAt(0)}</div>
                            <div>
                               <div className="flex items-center gap-2 font-black text-xl">{u.name}<span className="bg-gray-100 px-2 py-0.5 rounded text-[9px] font-bold tracking-widest">{u.class}</span></div>
                               <div className="text-sm opacity-40 font-bold">{u.email}</div>
                            </div>
                         </div>
                         <div className="flex gap-3">
                            <button onClick={() => handleRejectUser(u.email)} className="bg-red-50 text-red-600 px-6 py-3 rounded-xl text-xs font-black hover:bg-red-500 hover:text-white transition-colors">不承認 (削除)</button>
                            <button onClick={() => handleApproveUser(u.email)} className="bg-black text-white px-6 py-3 rounded-xl text-xs font-black shadow-lg hover:scale-105 transition-transform flex items-center gap-2"><span className="material-icons-round text-sm">verified_user</span> 承認する</button>
                         </div>
                      </div>
                    ))}
                    {pendingUsers.length === 0 && <div className="text-center py-24 opacity-20 font-black text-2xl">承認待ちアカウントはありません</div>}
                 </div>
               )}
            </div>
          )}
        </div>
      </main>

      {/* Right Sidebar */}
      <aside className="bg-bg-body dark:bg-bg-dark border-l p-8 space-y-10 hidden lg:block overflow-y-auto">
         <div className="bg-white p-6 rounded-3xl shadow-sm border border-gray-50">
            <div className="font-bold text-primary mb-4 flex items-center gap-2 text-sm"><span className="material-icons-round text-sm">search</span>検索</div>
            <input type="text" placeholder="キーワード検索..." className="w-full bg-gray-50 p-4 rounded-2xl text-xs outline-none focus:ring-2 ring-primary/20" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
         </div>
         <div>
            <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2"><span className="material-icons-round text-sm">folder</span>カテゴリー</h4>
            <div className="flex flex-wrap gap-2">
              {['all', ...CATEGORIES].map(c => (
                <button key={c} onClick={() => setCategoryFilter(c)} className={`px-4 py-2 rounded-xl text-[10px] font-black border transition-all ${categoryFilter === c ? 'bg-primary text-white border-primary shadow-lg shadow-primary/20' : 'bg-white hover:border-primary/30'}`}>{c === 'all' ? '全て' : c}</button>
              ))}
            </div>
         </div>
      </aside>

      {/* Modals */}
      {isPostModalOpen && (
        <div className="fixed inset-0 z-[100] bg-black/40 backdrop-blur-md flex items-center justify-center p-4">
           <div className="bg-white w-full max-w-3xl rounded-[3rem] shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
              <div className="p-10 bg-primary text-white flex justify-between items-center"><h2 className="text-3xl font-black">意見を投稿する</h2><button onClick={() => setIsPostModalOpen(false)} className="w-10 h-10 rounded-full hover:bg-white/20 flex items-center justify-center"><span className="material-icons-round">close</span></button></div>
              <div className="p-10 flex-1 overflow-y-auto space-y-8">
                 <input type="text" placeholder="タイトル" className="w-full text-3xl font-black border-b-2 pb-6 outline-none focus:border-primary transition-colors" value={postForm.title} onChange={e => setPostForm({...postForm, title: e.target.value})} />
                 <textarea placeholder="内容を詳しく入力してください..." className="w-full min-h-[250px] p-8 bg-gray-50 rounded-[2.5rem] outline-none resize-none text-lg leading-relaxed focus:bg-white focus:ring-2 ring-primary/5 transition-all" value={postForm.content} onChange={e => setPostForm({...postForm, content: e.target.value})} />
                 <div className={`p-8 rounded-[2rem] border-2 transition-all ${isAIApproved ? 'bg-green-50 border-green-200' : 'bg-primary/5 border-primary/10'}`}>
                    <div className="flex justify-between items-center mb-4"><h5 className="font-black text-primary flex items-center gap-2"><span className="material-icons-round text-sm">psychology</span> AIアドバイザー</h5>{!isAIApproved && <button onClick={handleAIAnalyze} disabled={aiResult.loading} className="bg-primary text-white px-6 py-2 rounded-full text-xs font-black shadow-lg disabled:opacity-50">{aiResult.loading ? '分析中...' : 'チェック実行'}</button>}</div>
                    {aiResult.result && <p className="text-sm leading-relaxed opacity-70 mb-2 font-medium">{aiResult.result.advice}</p>}
                    {isAIApproved && <div className="text-[10px] font-black text-green-600 uppercase flex items-center gap-1"><span className="material-icons-round text-sm">verified</span> 投稿準備完了</div>}
                 </div>
              </div>
              {isAIApproved && <div className="p-10 border-t flex justify-end"><button onClick={handlePostSubmit} className="bg-primary text-white font-black px-16 py-5 rounded-[1.5rem] shadow-2xl hover:scale-105 transition-transform">送信する</button></div>}
           </div>
        </div>
      )}

      {selectedProposalId && proposals.find(p => p.id === selectedProposalId) && (
         <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-white w-full max-w-4xl rounded-[3.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
               {(() => {
                 const p = proposals.find(x => x.id === selectedProposalId)!;
                 return (
                   <>
                     <div className="p-12 bg-primary text-white flex justify-between items-start">
                        <div><StatusBadge status={p.status} /><h3 className="text-4xl font-black mt-6 tracking-tight">{p.title}</h3></div>
                        <button onClick={() => setSelectedProposalId(null)} className="w-12 h-12 rounded-full hover:bg-white/20 flex items-center justify-center transition-colors"><span className="material-icons-round text-2xl">close</span></button>
                     </div>
                     <div className="p-12 space-y-12 max-h-[70vh] overflow-y-auto">
                        <Stepper currentStatus={p.status} />
                        <div className="flex gap-4 items-center opacity-40 font-bold text-sm uppercase tracking-widest"><span className="material-icons-round text-sm">folder</span>{p.category}</div>
                        <p className="text-2xl opacity-80 whitespace-pre-wrap leading-relaxed">{p.content}</p>
                        {p.adminResponse && <div className="bg-purple-50 p-10 rounded-[2.5rem] border-l-8 border-primary shadow-sm"><h5 className="font-black text-primary mb-4 flex items-center gap-2 text-xl"><span className="material-icons-round">forum</span> 生徒会からの回答</h5><p className="text-lg leading-relaxed">{p.adminResponse}</p></div>}
                        <div className="pt-10 border-t flex justify-between items-center">
                           <div className="text-4xl font-black text-primary tracking-tighter"><span className="text-xs opacity-40 uppercase mr-3">賛同者数</span>{p.signatures.length}</div>
                           <button onClick={() => toggleSignature(p.id)} className={`px-16 py-6 rounded-[2rem] font-black text-lg shadow-2xl transition-all ${user && p.signatures.find(s => s.userId === user.id) ? 'bg-pink-100 text-pink-600' : 'bg-primary text-white hover:scale-105'}`}>
                             {user && p.signatures.find(s => s.userId === user.id) ? '賛同済み' : '実名で賛同する'}
                           </button>
                        </div>
                     </div>
                   </>
                 );
               })()}
            </div>
         </div>
      )}

      {/* Admin Edit Modal */}
      {adminEditId && (
        <div className="fixed inset-0 z-[110] bg-black/60 backdrop-blur-md flex items-center justify-center p-4">
           <div className="bg-white w-full max-w-xl rounded-[3rem] p-10 space-y-8 animate-in zoom-in-95">
              <h3 className="text-2xl font-black flex items-center gap-3"><span className="material-icons-round text-primary">edit</span> 意見の更新</h3>
              <div><label className="block text-[10px] font-black opacity-40 mb-3 uppercase tracking-widest">ステータス変更</label>
                <div className="flex flex-wrap gap-2">{STATUS_STEPS.map(s => <button key={s} onClick={() => setAdminStatusSelect(s)} className={`px-5 py-2.5 rounded-xl text-xs font-bold border-2 transition-all ${adminStatusSelect === s ? 'bg-primary border-primary text-white shadow-lg shadow-primary/20' : 'bg-gray-50 border-transparent hover:border-gray-200'}`}>{s}</button>)}</div>
              </div>
              <div><label className="block text-[10px] font-black opacity-40 mb-3 uppercase tracking-widest">生徒会としての公式回答</label><textarea className="w-full bg-gray-50 p-6 rounded-2xl h-40 outline-none focus:ring-2 ring-primary/20" value={adminResponseText} onChange={e => setAdminResponseText(e.target.value)} placeholder="検討状況や結論を入力してください" /></div>
              <div className="flex justify-end gap-4"><button onClick={() => setAdminEditId(null)} className="font-bold opacity-30 hover:opacity-100 px-4">キャンセル</button><button onClick={handleAdminUpdate} className="bg-primary text-white font-black px-10 py-4 rounded-xl shadow-xl hover:scale-105 transition-transform">変更を保存</button></div>
           </div>
        </div>
      )}
    </div>
  );
};

export default App;
